/* source-style: inline-1 */
:root {
      --bg:#f7f5ff; --bg2:#eef6ff; --card:#ffffffcc; --card2:#ffffffef;
      --text:#17223b; --muted:#66728a; --line:#E2E4DD; --primary:#243B73; --primary2:#1B2F60;
      --soft:#E9EDFA; --pink:#ff4f79; --green:#23c79a; --blue:#7db5ff; --yellow:#ffd36d;
      --shadow:0 22px 60px rgba(28,37,25,.13); --shadow2:0 12px 28px rgba(28,37,25,.09);
      --radius:26px; --radius2:18px; --jp:"Noto Sans JP",sans-serif; --font:"Plus Jakarta Sans",system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
    }
    * { box-sizing:border-box; }
    html { scroll-behavior:smooth; }
    body {
      margin:0; min-height:100vh; font-family:var(--font); color:var(--text); overflow-x:hidden;
      background:
        radial-gradient(circle at 12% 5%,rgba(188,168,255,.55),transparent 32%),
        radial-gradient(circle at 92% 8%,rgba(198,231,255,.65),transparent 36%),
        radial-gradient(circle at 75% 85%,rgba(255,209,226,.58),transparent 35%),
        linear-gradient(135deg,#fafcff,#F4F5F0 52%,#fff7fb);
      user-select:none;
    }
    body::before { content:""; position:fixed; inset:0; pointer-events:none; background:linear-gradient(90deg,rgba(255,255,255,.15),transparent 35%,rgba(255,255,255,.2)); z-index:-1; }
    input, textarea, select { user-select:text; font:inherit; }
    button { font:inherit; cursor:pointer; }
    img { -webkit-user-drag:none; user-select:none; }
    .jp { font-family:var(--jp); }
    .hidden { display:none!important; }
    .app { min-height:100vh; padding-top:88px; }
    .top-nav {
      position:fixed; top:0; left:0; right:0; height:78px; z-index:20; display:flex; align-items:center; justify-content:center;
      background:rgba(255,255,255,.82); border-bottom:1px solid rgba(36,59,115,.12); backdrop-filter:blur(18px); box-shadow:0 8px 24px rgba(36,59,115,.08);
    }
    .nav-inner { width:min(1180px,calc(100% - 34px)); display:flex; align-items:center; justify-content:space-between; gap:16px; }
    .brand { display:flex; align-items:center; gap:11px; font-weight:900; color:#243B73; letter-spacing:-.03em; white-space:nowrap; }
    .brand-icon { width:42px;height:42px;display:grid;place-items:center;border-radius:15px;background:linear-gradient(135deg,var(--primary),#35549D);color:#fff;box-shadow:0 10px 24px rgba(36,59,115,.22); }
    .nav-links { display:flex; align-items:center; gap:34px; }
    .nav-link {
      border:0;background:transparent;color:#4d5870;font-weight:800;font-size:16px;padding:20px 0;position:relative;
    }
    .nav-link.active,.nav-link:hover { color:var(--primary); }
    .nav-link.active::after { content:"";position:absolute;left:0;right:0;bottom:8px;height:4px;border-radius:99px;background:var(--primary); }
    .user-menu { position:relative; }
    .user-btn {
      min-height:50px;border:1px solid var(--line);border-radius:18px;background:#fff;padding:0 22px;display:flex;align-items:center;gap:12px;
      color:#243B73;font-weight:900;box-shadow:var(--shadow2);
    }
    .dropdown { position:absolute;right:0;top:60px;min-width:210px;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow);padding:10px;display:none; }
    .dropdown.show { display:block; }
    .drop-item { width:100%;border:0;background:transparent;padding:12px 12px;border-radius:13px;text-align:left;font-weight:800;color:#4d5870;display:flex;gap:10px;align-items:center; }
    .drop-item:hover { background:var(--soft); color:var(--primary2); }
    .page { width:min(1380px,calc(100% - 54px)); margin:0 auto; padding:28px 0 54px; display:none; animation:fade .25s ease both; }
    .page.active { display:block; }
    @keyframes fade { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:none} }
    .glass {
      background:linear-gradient(145deg,rgba(255,255,255,.91),rgba(255,255,255,.72));border:1px solid rgba(255,255,255,.86);
      border-radius:var(--radius);box-shadow:var(--shadow);backdrop-filter:blur(18px);
    }
    .hero { min-height:650px; display:grid; grid-template-columns:1.05fr .95fr; gap:28px; align-items:center; padding:48px; overflow:hidden; position:relative; }
    .hero::after { content:"";position:absolute;right:-80px;top:-80px;width:300px;height:300px;border-radius:50%;background:rgba(36,59,115,.12); }
    .badge { display:inline-flex; align-items:center; gap:8px; padding:9px 14px; border-radius:999px; background:var(--soft); color:var(--primary2); font-weight:900; font-size:13px; }
    h1 { font-size:clamp(36px,5vw,70px); line-height:1.02; letter-spacing:-.06em; margin:18px 0; color:#071b45; }
    h2 { font-size:clamp(28px,3.2vw,46px); line-height:1.1; letter-spacing:-.05em; margin:0 0 10px; color:#071b45; }
    h3 { margin:0 0 8px; color:#071b45; }
    p { color:var(--muted); line-height:1.65; }
    .hero-actions,.row-actions { display:flex; flex-wrap:wrap; gap:12px; align-items:center; }
    .btn {
      min-height:48px; border:0; border-radius:15px; padding:0 18px; display:inline-flex; align-items:center; justify-content:center; gap:9px;
      font-weight:900; color:#fff; background:linear-gradient(135deg,var(--primary),var(--primary2)); box-shadow:0 14px 28px rgba(36,59,115,.25);
      transition:.18s ease;
    }
    .btn:hover { transform:translateY(-2px); filter:brightness(1.02); }
    .btn:disabled { opacity:.48; cursor:not-allowed; transform:none; box-shadow:none; }
    .btn.secondary { color:#4e5970; background:#fff; border:1px solid var(--line); box-shadow:var(--shadow2); }
    .btn.soft { color:var(--primary2); background:var(--soft); box-shadow:none; }
    .btn.danger { background:#fff; color:#ff285d; border:1px solid rgba(255,40,93,.35); box-shadow:none; }
    .btn.good { background:linear-gradient(135deg,#1fc59a,#16a374); }
    .btn.bad { background:linear-gradient(135deg,#ff4f79,#f02f56); }
    .hero-visual { min-height:460px; display:grid; place-items:center; position:relative; }
    .big-kana { width:min(390px,85%); aspect-ratio:1; border-radius:42px; display:grid; place-items:center; background:linear-gradient(145deg,#fff,#F4F5F0); box-shadow:var(--shadow); position:relative; }
    .big-kana span { font-family:var(--jp); font-size:132px; color:var(--primary); font-weight:900; }
    .float-card { position:absolute; padding:16px; border-radius:22px; background:#fff; box-shadow:var(--shadow2); border:1px solid var(--line); font-weight:900; }
    .float-card.one { left:2%; top:12%; } .float-card.two { right:0; bottom:15%; } .float-card.three { left:12%; bottom:4%; }
    .info-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; margin:24px 0; }
    .info-card { padding:18px; border-radius:20px; background:rgba(255,255,255,.82); border:1px solid rgba(36,59,115,.14); box-shadow:var(--shadow2); }
    .info-card i { width:40px;height:40px;display:grid;place-items:center;border-radius:14px;margin-bottom:10px;color:var(--primary);background:var(--soft); }
    .info-card strong { display:block;font-size:28px;color:#071b45;line-height:1; }
    .info-card span { color:var(--muted);font-weight:700;font-size:13px; }
    .choice-chip {
      min-height:44px;border:1px solid var(--line);background:#fff;color:#536078;border-radius:999px;padding:0 16px;font-weight:900;display:inline-flex;gap:8px;align-items:center;justify-content:center;
    }
    .choice-chip.active { color:#fff;background:linear-gradient(135deg,var(--primary),var(--primary2));border-color:transparent; }
    .choice-chip:disabled { opacity:.45; cursor:not-allowed; }
    .layout { display:grid; grid-template-columns:275px 1fr; gap:28px; align-items:start; }
    .sidebar { padding:22px; position:sticky; top:104px; }
    .side-btn { width:100%; min-height:58px; border:0; background:transparent; border-radius:17px; display:flex; align-items:center; gap:15px; padding:0 18px; color:#526078; font-weight:900; margin-bottom:10px; text-align:left; }
    .side-btn.active,.side-btn:hover { color:#fff; background:linear-gradient(135deg,var(--primary),var(--primary2)); box-shadow:0 12px 24px rgba(36,59,115,.22); }
    .stat-box { margin-top:24px; padding:22px; }
    .mini-stat { display:flex; align-items:center; gap:15px; margin-top:18px; }
    .mini-icon { width:46px;height:46px;border-radius:17px;display:grid;place-items:center;background:var(--soft);color:var(--primary);font-size:20px; }
    .mini-stat strong { display:block;font-size:23px;line-height:1;color:#071b45; }
    .mini-stat span { color:var(--muted);font-size:13px;font-weight:700; }
    .bab19-breakdown { margin-top:16px; padding-top:4px; border-top:1px solid rgba(36,59,115,.12); }
    .bab19-breakdown .mini-stat { margin-top:14px; }
    .content-card { padding:34px 38px; min-height:650px; }
    .notice { display:flex; gap:18px; align-items:flex-start; padding:20px; border-radius:22px; background:linear-gradient(120deg,#EEF1F8,#eef6ff); border:1px solid var(--line); margin:24px 0; }
    .notice i { width:44px;height:44px;display:grid;place-items:center;border-radius:15px;background:#fff;color:var(--primary);font-size:20px;flex:0 0 auto; }
    .search-row { display:flex; gap:12px; flex-wrap:wrap; margin:22px 0; }
    .search-box { position:relative; flex:1 1 300px; }
    .search-box i { position:absolute; left:18px; top:50%; transform:translateY(-50%); color:#72809a; }
    .input, select {
      width:100%; min-height:54px; border:1px solid #dbe2f3; background:#fff; border-radius:17px; padding:0 17px; outline:none; color:#24304a; font-weight:700;
    }
    .search-box .input { padding-left:48px; }
    .input:focus, select:focus { border-color:rgba(36,59,115,.55); box-shadow:0 0 0 4px rgba(36,59,115,.1); }
    .vocab-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(240px,1fr)); gap:16px; }
    .vocab-card { padding:18px; border-radius:22px; background:#fff; border:1px solid #E2E4DD; box-shadow:var(--shadow2); position:relative; overflow:hidden; }
    .vocab-top { display:flex; gap:13px; align-items:center; }
    .thumb { width:58px;height:58px;border-radius:18px;object-fit:contain;background:#F7F7F2;border:1px solid #E7E9E2;flex:0 0 auto; }
    .vocab-jp { font-family:var(--jp);font-size:clamp(20px,2vw,27px);font-weight:900;color:#081a40;line-height:1.2;overflow-wrap:anywhere;word-break:normal; }
    .vocab-kana { color:#4d5870;font-weight:700;font-size:13px;line-height:1.35;margin-top:4px;overflow-wrap:anywhere; }
    .vocab-romaji { color:var(--primary);font-weight:900;font-size:13px; }
    .vocab-id { margin:13px 0;color:#46536b;font-weight:700;line-height:1.45; }
    .tag-row { display:flex; flex-wrap:wrap; gap:7px; }
    .tag { padding:6px 9px;border-radius:999px;background:var(--soft);color:var(--primary2);font-size:11px;font-weight:900; }
    .tag.green { background:#e9fbf5;color:#148060; } .tag.pink { background:#ffeaf0;color:#d83362; }
    .tag.verb-transitivity { background:#fff4d8; color:#8a5a00; display:inline-flex; align-items:center; gap:5px; }
    .card-actions { display:flex;gap:8px;margin-top:14px; }
    .icon-btn { width:42px;height:42px;border:1px solid var(--line);border-radius:14px;background:#fff;color:var(--primary);display:grid;place-items:center;box-shadow:var(--shadow2); }
    .icon-btn.active { color:#fff;background:linear-gradient(135deg,var(--primary),var(--primary2)); }
    .empty { padding:32px;border:1px dashed #AEB9D1;border-radius:24px;background:rgba(255,255,255,.58);color:#59657d;font-weight:800;text-align:left; }
    .empty h3 { font-size:24px; }
    .quiz-grid { display:grid; grid-template-columns:minmax(0,1.45fr) minmax(320px,.9fr); gap:28px; align-items:stretch; }
    .quiz-card-wrap { min-height:620px; padding:28px; display:flex; flex-direction:column; }
    .flashcard { flex:1; min-height:530px; perspective:1300px; }
    .flash-inner { width:100%; height:100%; position:relative; transform-style:preserve-3d; transition:transform .6s cubic-bezier(.2,.8,.2,1); }
    .flashcard.flipped .flash-inner { transform:rotateY(180deg); }
    .flash-face {
      position:absolute; inset:0; backface-visibility:hidden; border-radius:24px; background:#fff; border:1px solid #E2E4DD; overflow:hidden; display:flex; flex-direction:column; justify-content:space-between; padding:22px;
    }
    .flash-back { transform:rotateY(180deg); background:linear-gradient(145deg,#fff,#F7F7F2); }
    .flash-labels { display:flex; align-items:center; justify-content:space-between; gap:12px; }
    .flash-main { flex:1; display:grid; place-items:center; text-align:center; padding:30px 10px; }
    .question-text { font-size:clamp(34px,5vw,72px);font-weight:900;letter-spacing:-.05em;color:#071b45;line-height:1.15;overflow-wrap:anywhere; }
    .question-text.jp { font-family:var(--jp); letter-spacing:-.02em; }
    .answer-area { display:grid; gap:18px; justify-items:center; text-align:center; }
    .answer-img { width:min(390px,82%); height:260px; object-fit:contain; border-radius:22px; background:linear-gradient(135deg,#F7F7F2,#f0f6ff); border:1px solid #E7E9E2; }
    .answer-main { font-size:clamp(30px,4vw,54px); font-weight:900; color:#071b45; line-height:1.18; overflow-wrap:anywhere; }
    .answer-main.jp { font-family:var(--jp); }
    .answer-sub { color:var(--primary); font-weight:900; }
    .flip-help { text-align:center;color:#6b7890;font-weight:800;border-top:1px solid #edf0f7;padding-top:14px; }
    .control-panel { padding:22px; display:flex; flex-direction:column; gap:14px; }
    .control-row { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
    .metric { padding:16px; border-radius:18px; background:#fff; border:1px solid #edf0f7; }
    .metric span { color:var(--primary);font-weight:900;font-size:13px; }
    .metric strong { display:block;color:#071b45;font-size:29px;line-height:1.05;font-variant-numeric:tabular-nums; }
    .bar { height:9px;border-radius:999px;background:#E9EDFA;overflow:hidden;margin:9px 0; }
    .bar > div { height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--primary),#57d5e7);transition:.2s linear; }
    .control-btn { width:100%; min-height:48px; border:1px solid #e2e6f2; border-radius:14px; background:#fff; color:#60708a; font-weight:900; display:flex;align-items:center;justify-content:center;gap:8px; }
    .control-btn:disabled { opacity:.45; cursor:not-allowed; }
    .mic-box { padding:16px; border-radius:20px; background:#fff; border:1px solid #edf0f7; display:flex; gap:14px; align-items:center; }
    .switch { margin-left:auto; width:62px;height:36px;border:0;border-radius:999px;background:#d7deed;position:relative; }
    .switch::after { content:"";position:absolute;width:28px;height:28px;left:4px;top:4px;border-radius:50%;background:#fff;box-shadow:0 5px 12px rgba(0,0,0,.15);transition:.2s; }
    .switch.on { background:linear-gradient(135deg,var(--primary),#60d8c0); }
    .switch.on::after { transform:translateX(26px); }
    .listen-wave { display:flex; gap:6px; justify-content:center; align-items:center; min-height:44px; border-radius:14px; background:#f4ecff; color:var(--primary); font-weight:900; }
    .listen-wave b { width:16px;height:8px;border-radius:99px;background:#56c9a9; animation:wave .8s infinite alternate; }
    .listen-wave b:nth-child(2){animation-delay:.12s} .listen-wave b:nth-child(3){animation-delay:.24s} .listen-wave b:nth-child(4){animation-delay:.36s}
    @keyframes wave { to{height:18px} }
    .result-head { margin-bottom:18px; }
    .breadcrumb { display:inline-flex; gap:8px; align-items:center; padding:8px 13px; border-radius:999px; background:var(--soft); color:var(--primary2); font-weight:900; font-size:12px; margin-bottom:14px; }
    .result-grid { display:grid; grid-template-columns:1.45fr .85fr; gap:24px; align-items:stretch; }
    .score-card { padding:26px; display:grid; grid-template-columns:180px 1fr; gap:24px; align-items:center; background:linear-gradient(135deg,#fff,#fff2fb); }
    .circle { width:166px;height:166px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--primary) 0deg,#eee7ff 0);position:relative; }
    .circle::before { content:"";position:absolute;inset:17px;border-radius:50%;background:#fff; }
    .circle strong { position:relative;font-size:42px;color:#071b45;font-weight:900; }
    .result-stats { padding:22px; display:grid; grid-template-columns:repeat(2,1fr); gap:14px; }
    .result-stat { padding:18px; border-radius:18px; background:#fff; border:1px solid #e6e0ff; display:flex; gap:14px; align-items:center; }
    .result-stat i { width:44px;height:44px;display:grid;place-items:center;border-radius:16px;background:var(--soft);color:var(--primary); }
    .result-stat strong { display:block;font-size:24px;color:#071b45;line-height:1; }
    .filters { display:flex; gap:10px; flex-wrap:wrap; margin:18px 0; justify-content:flex-end; }
    .table-card { padding:22px; margin-top:24px; }
    .table-wrap { overflow-x:auto; border:1px solid #e5e1f7; border-radius:18px; background:#fff; }
    table { width:100%; border-collapse:collapse; min-width:760px; }
    th,td { padding:13px 15px; border-bottom:1px solid #eef0f7; text-align:left; vertical-align:middle; }
    th { background:#f4efff; color:var(--primary2); font-size:12px; text-transform:uppercase; letter-spacing:.02em; }
    td { font-size:14px; font-weight:700; color:#28344e; }
    .status { padding:6px 10px;border-radius:999px;font-size:12px;font-weight:900;display:inline-flex;gap:6px;align-items:center; }
    .status.ok { background:#dcfaef;color:#128362; } .status.no { background:#ffe1ea;color:#d8345f; }
    .admin-stats { display:grid; grid-template-columns:repeat(5,1fr); gap:16px; margin:22px 0; }
    .admin-stat { padding:20px; border-radius:20px; background:#fff; border:1px solid #E2E4DD; box-shadow:var(--shadow2); display:flex;align-items:center;gap:14px; }
    .admin-stat i { width:54px;height:54px;display:grid;place-items:center;border-radius:18px;background:var(--soft);color:var(--primary);font-size:20px; }
    .admin-stat strong { display:block;font-size:25px;color:#071b45;line-height:1; } .admin-stat span { font-size:12px;color:var(--muted);font-weight:800; }
    .avatar { width:36px;height:36px;border-radius:50%;display:inline-grid;place-items:center;background:linear-gradient(135deg,var(--primary),#58cead);color:#fff;font-weight:900;margin-right:8px; }
    .modal {
      position:fixed; inset:0; z-index:80; display:none; place-items:center; padding:20px; background:rgba(19,23,40,.45); backdrop-filter:blur(14px);
    }
    .modal.show { display:grid; }
    .modal-card {
      width:min(930px,100%); max-height:min(88vh,840px); overflow:auto; padding:28px; border-radius:28px; background:rgba(255,255,255,.97); border:1px solid rgba(255,255,255,.9); box-shadow:0 30px 100px rgba(22,29,48,.28);
    }
    .modal-card.small { width:min(480px,100%); }
    .modal-title { text-align:center; margin-bottom:22px; }
    .modal-title .kana-icon { width:72px;height:72px;margin:0 auto 14px;display:grid;place-items:center;border-radius:22px;background:linear-gradient(135deg,var(--primary),#35549D);color:#fff;font-family:var(--jp);font-size:36px;font-weight:900;box-shadow:0 14px 30px rgba(36,59,115,.24); }
    .close-x { float:right; width:46px;height:46px;border:1px solid #e4e8f3;background:#fff;border-radius:50%;color:#1d2940;font-size:22px;display:grid;place-items:center; }
    .step-block { margin:18px 0; }
    .step-block h3 { font-size:18px; }
    .option-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
    .option-card {
      min-height:88px; border:1px solid #dde4f5; border-radius:20px; background:#fff; padding:18px; text-align:left; font-weight:900; color:#1b2741; box-shadow:var(--shadow2);
    }
    .option-card small { display:block;margin-top:8px;color:var(--muted);font-weight:700;line-height:1.4; }
    .option-card.active { border-color:var(--primary); background:#E9EDFA; color:var(--primary); box-shadow:0 0 0 4px rgba(36,59,115,.12); }
    .option-card:disabled { opacity:.48; cursor:not-allowed; box-shadow:none; transform:none; }
    .quiz-setting-subtitle { display:block; margin:14px 0 9px; color:#071b45; font-weight:750; }
    .quiz-setting-note { margin:8px 0 0; font-size:13px; line-height:1.55; color:var(--muted); font-weight:550; }
    .multi-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(118px,1fr)); gap:10px; }
    .check-pill { min-height:44px; border:1px solid #dde4f5; border-radius:999px; display:flex; align-items:center; justify-content:center; padding:0 12px; font-weight:900; background:#fff; color:#536078; }
    .check-pill input { display:none; }
    .check-pill:has(input:checked) { border-color:var(--primary); background:var(--soft); color:var(--primary2); }
    .toast { position:fixed; right:18px; bottom:18px; z-index:150; display:grid; gap:10px; max-width:360px; }
    .toast-item { padding:14px 16px; border-radius:18px; background:#fff; border:1px solid var(--line); box-shadow:var(--shadow); color:#27334d; font-weight:800; animation:fade .2s ease both; }
    .loader { position:fixed; inset:0; z-index:200; display:grid; place-items:center; background:linear-gradient(135deg,#fbfcff,#F4F5F0); }
