    :root {
      --background:#f7f7f2;
      --background-secondary:#f0f1ec;
      --surface:#ffffff;
      --surface-hover:#fafaf7;
      --surface-muted:#f3f4ef;
      --text-primary:#171917;
      --text-secondary:#666b66;
      --text-muted:#8a8f89;
      --border:#e2e4dd;
      --border-strong:#d4d7cf;
      --primary:#243b73;
      --primary-hover:#1b2f60;
      --primary-soft:#e9edfa;
      --accent:#e84b3c;
      --accent-hover:#d63c30;
      --accent-soft:#fcece9;
      --matcha:#63785d;
      --matcha-soft:#ebf0e8;
      --success:#278b62;
      --success-soft:#e3f4ec;
      --warning:#d49327;
      --warning-soft:#fff3d9;
      --danger:#d84949;
      --danger-soft:#fdeaea;
      --bg:var(--background);
      --bg2:var(--background-secondary);
      --card:var(--surface);
      --card2:var(--surface);
      --text:var(--text-primary);
      --muted:var(--text-secondary);
      --line:var(--border);
      --primary2:var(--primary-hover);
      --soft:var(--primary-soft);
      --pink:var(--accent);
      --green:var(--success);
      --blue:#607db3;
      --yellow:var(--warning);
      --shadow:0 18px 55px rgba(35,42,32,.10);
      --shadow2:0 6px 24px rgba(35,42,32,.065);
      --radius:20px;
      --radius2:16px;
      --radius-xs:8px;
      --radius-sm:12px;
      --radius-md:16px;
      --radius-lg:20px;
      --radius-xl:28px;
      --ease-out:cubic-bezier(.22,1,.36,1);
    }

    html { background:var(--background); }
    body {
      background:
        radial-gradient(circle at 92% 5%,rgba(232,75,60,.055),transparent 27rem),
        radial-gradient(circle at 5% 18%,rgba(36,59,115,.055),transparent 30rem),
        var(--background) !important;
      color:var(--text-primary);
      font-weight:400;
      letter-spacing:-.008em;
      user-select:auto;
    }
    body::before {
      opacity:.32;
      background-image:linear-gradient(rgba(36,59,115,.022) 1px,transparent 1px),linear-gradient(90deg,rgba(36,59,115,.022) 1px,transparent 1px);
      background-size:40px 40px;
    }
    h1,h2,h3 { color:var(--text-primary); }
    h1 { font-weight:700; letter-spacing:-.055em; }
    h2 { font-weight:700; letter-spacing:-.04em; }
    h3 { font-weight:650; letter-spacing:-.025em; }
    p { color:var(--text-secondary); }
    button,input,select { font-family:var(--font); }
    button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible {
      outline:3px solid rgba(36,59,115,.2) !important;
      outline-offset:3px;
    }

    .app { padding-top:92px; }
    .page {
      width:min(1320px,calc(100% - 48px));
      padding:34px 0 64px;
      animation:wikaruPageEnter .34s var(--ease-out) both;
    }
    @keyframes wikaruPageEnter { from{opacity:0;transform:translateY(12px)} to{opacity:1;transform:none} }

    .glass {
      background:var(--surface) !important;
      border:1px solid var(--border) !important;
      box-shadow:var(--shadow2) !important;
      backdrop-filter:none !important;
      -webkit-backdrop-filter:none !important;
    }


    .top-nav {
      height:76px !important;
      background:rgba(247,247,242,.92) !important;
      border-bottom:1px solid rgba(212,215,207,.82) !important;
      box-shadow:none !important;
      backdrop-filter:blur(14px) saturate(1.1) !important;
    }
    .nav-inner { width:min(1320px,calc(100% - 48px)) !important; gap:24px !important; }
    .brand { min-width:255px !important; gap:12px !important; color:var(--primary); }
    .brand-icon.wikaru-mark {
      width:46px !important;
      height:46px !important;
      border-radius:0 !important;
      background:none !important;
      color:var(--primary);
      box-shadow:none !important;
      overflow:visible !important;
      flex:0 0 auto;
