/* source-style: wikaru-v4-theme */
:root {
  --wikaru-navy:#243B73;
  --wikaru-navy-hover:#1B2F60;
  --wikaru-navy-soft:#E9EDFA;
  --wikaru-red:#E84B3C;
  --wikaru-red-soft:#FCECE9;
  --wikaru-matcha:#63785D;
  --wikaru-matcha-soft:#EBF0E8;
  --wikaru-paper:#F7F7F2;
  --wikaru-ink:#171917;
  --wikaru-muted:#687069;
  --wikaru-line:#E2E4DD;
  --wikaru-surface:#FFFFFF;
  --wikaru-surface-soft:#F3F4EF;
  --wikaru-shadow:0 8px 24px rgba(35,42,32,.07);
}


#materialPage {
  --material-primary:var(--wikaru-navy);
  --material-accent:var(--wikaru-red);
  --material-success:var(--wikaru-matcha);
  color:var(--wikaru-ink);
}
#materialPage .content-card {
  background:var(--wikaru-surface)!important;
  border:1px solid var(--wikaru-line)!important;
  box-shadow:0 10px 30px rgba(35,42,32,.055)!important;
}
#materialPage .notice {
  background:linear-gradient(135deg,var(--wikaru-navy-soft),#f6f7f2)!important;
  border-color:#d8deec!important;
  box-shadow:none!important;
}
#materialPage .notice i { background:var(--wikaru-surface)!important; color:var(--wikaru-navy)!important; box-shadow:none!important; }
#materialPage .notice h3 { color:var(--wikaru-navy)!important; }
#materialPage .notice p { color:#59635d!important; }
#materialPage .material-toolbar,
#materialPage .search-row {
  background:rgba(255,255,255,.94)!important;
  border-color:var(--wikaru-line)!important;
  box-shadow:0 8px 22px rgba(35,42,32,.055)!important;
}
#materialPage .input,
#materialPage select,
#materialPage .search-box .input {
  color:var(--wikaru-ink)!important;
  background:var(--wikaru-surface)!important;
  border-color:var(--wikaru-line)!important;
  box-shadow:none!important;
}
#materialPage .input:focus,
#materialPage select:focus {
  border-color:rgba(36,59,115,.55)!important;
  box-shadow:0 0 0 4px rgba(36,59,115,.10)!important;
}


#materialPage :is(
  [class$="-hero"], [class*="-hero "],
  [class$="-panel"], [class*="-panel "],
  [class$="-section"], [class*="-section "],
  [class$="-wrap"],
  [class$="-card"], [class*="-card "],
  [class$="-item"], [class*="-item "],
  [class$="-box"], [class*="-box "]
) {
  border-color:var(--wikaru-line)!important;
}
#materialPage :is(
  [class$="-card"], [class*="-card "],
  [class$="-item"], [class*="-item "],
  [class$="-box"], [class*="-box "]
) {
  background:var(--wikaru-surface)!important;
  box-shadow:var(--wikaru-shadow)!important;
}
#materialPage :is([class$="-hero"],[class*="-hero "]) {
  background:
    radial-gradient(circle at 88% 18%,rgba(232,75,60,.09),transparent 27%),
    linear-gradient(135deg,#f4f6fb 0%,#fbfbf7 58%,#f5f0ea 100%)!important;
  box-shadow:none!important;
}
#materialPage :is([class$="-panel"],[class*="-panel "],[class$="-section"],[class*="-section "]) {
  background:var(--wikaru-surface-soft)!important;
  box-shadow:none!important;
}
#materialPage :is(
  [class$="-badge"], [class*="-badge "],
  [class$="-kicker"], [class*="-kicker "],
  [class$="-label"], [class*="-label "],
  [class$="-count"], [class*="-count "]
) {
  background:var(--wikaru-navy-soft)!important;
  border-color:#d7deef!important;
  color:var(--wikaru-navy)!important;
  box-shadow:none!important;
}
#materialPage :is(
  h2,h3,h4,strong,
  .vocab-jp,
  [class$="-title"], [class*="-title "],
  [class$="-kanji"], [class*="-kanji "],
  [class$="-jp"], [class*="-jp "]
) { color:var(--wikaru-ink)!important; }
#materialPage :is(
  p,
  [class$="-desc"], [class*="-desc "],
  [class$="-summary"], [class*="-summary "],
  [class$="-note"], [class*="-note "]
) { color:var(--wikaru-muted)!important; }


#materialPage .vocab-script-block { display:grid; align-content:center; min-width:0; gap:5px; }
#materialPage :is(.vocab-jp,[class$="-kanji"],[class*="-kanji "],[class$="-jp"],[class*="-jp "]) {
  font-family:var(--jp)!important;
  font-weight:700!important;
  line-height:1.28!important;
  letter-spacing:-.015em!important;
}
#materialPage .vocab-jp { font-size:clamp(23px,2vw,31px)!important; }
#materialPage :is(.vocab-kana,[class$="-kana"],[class*="-kana "]) {
  font-family:var(--jp)!important;
  color:#4f5d72!important;
  font-size:13.5px!important;
  font-weight:600!important;
  line-height:1.5!important;
  letter-spacing:.015em!important;
}
#materialPage :is(.vocab-romaji,[class$="-romaji"],[class*="-romaji "],[class$="-reading"],[class*="-reading "]) {
