/* source-style: wikaru-theme-motion-final */
html.theme-motion-enabled body,
html.theme-motion-enabled .top-nav,
html.theme-motion-enabled .bottom-nav,
html.theme-motion-enabled .glass,
html.theme-motion-enabled .modal-card,
html.theme-motion-enabled .modal-footer,
html.theme-motion-enabled .dropdown,
html.theme-motion-enabled .profile-menu-header,
html.theme-motion-enabled .vocab-card,
html.theme-motion-enabled .flash-face,
html.theme-motion-enabled .control-panel,
html.theme-motion-enabled .option-card,
html.theme-motion-enabled .choice-chip,
html.theme-motion-enabled .check-pill,
html.theme-motion-enabled .input,
html.theme-motion-enabled select {
  transition:
    background-color .42s ease,
    color .32s ease,
    border-color .32s ease,
    box-shadow .42s ease,
    filter .32s ease;
}

html.theme-motion-enabled :is(.btn,.control-btn,.icon-btn,.drop-item,.theme-toggle,.nav-lang-btn,.nav-fiction-toggle,.user-btn) {
  transition:
    transform .2s ease,
    background-color .42s ease,
    color .32s ease,
    border-color .32s ease,
    box-shadow .42s ease,
    filter .32s ease;
}

.theme-transition-overlay {
  position:fixed;
  inset:0;
  z-index:2500;
  overflow:hidden;
  pointer-events:none;
  isolation:isolate;
  contain:strict;
  opacity:1;
  transition:opacity .22s ease;
}
.theme-transition-overlay.is-fading { opacity:0; }

.theme-transition-circle {
  position:absolute;
  left:var(--theme-origin-x);
  top:var(--theme-origin-y);
  width:var(--theme-diameter);
  height:var(--theme-diameter);
  border-radius:50%;
  transform:translate(-50%,-50%) scale(.001);
  transform-origin:center;
  will-change:transform,opacity;
  animation:wikaruThemeRadialReveal .72s cubic-bezier(.2,.82,.22,1) both;
}
.theme-to-dark .theme-transition-circle {
  background:
    radial-gradient(circle at 50% 50%,rgba(126,157,242,.20) 0%,rgba(55,74,126,.13) 20%,transparent 42%),
    linear-gradient(145deg,#111C2A 0%,#0F1722 52%,#0A111B 100%);
  box-shadow:0 0 110px rgba(91,116,194,.23);
}
.theme-to-light .theme-transition-circle {
  background:
    radial-gradient(circle at 50% 50%,rgba(255,220,126,.30) 0%,rgba(255,244,205,.18) 24%,transparent 45%),
    linear-gradient(145deg,#FFFFFF 0%,#F7F8FA 52%,#EEF5FF 100%);
  box-shadow:0 0 110px rgba(255,220,126,.25);
}

.theme-transition-icon {
  position:absolute;
  left:var(--theme-icon-x);
  top:var(--theme-icon-y);
  width:76px;
  height:76px;
  border-radius:26px;
  display:grid;
  place-items:center;
  transform:translate(-50%,-50%);
  will-change:transform,opacity;
  animation:wikaruThemeIconEnter .72s cubic-bezier(.2,.8,.2,1) both;
  box-shadow:0 18px 50px rgba(0,0,0,.20),inset 0 1px 0 rgba(255,255,255,.35);
  backdrop-filter:blur(8px);
}
.theme-transition-icon i { font-size:31px; }
.theme-to-dark .theme-transition-icon {
  color:#EEF3FF;
  background:linear-gradient(145deg,rgba(120,148,235,.94),rgba(54,70,119,.94));
  border:1px solid rgba(221,230,255,.32);
}
.theme-to-light .theme-transition-icon {
  color:#8A6400;
  background:linear-gradient(145deg,rgba(255,244,184,.96),rgba(255,205,91,.96));
