}

.theme-transition-particles {
  position:absolute;
  left:var(--theme-icon-x);
  top:var(--theme-icon-y);
  width:1px;
  height:1px;
}
.theme-transition-particle {
  position:absolute;
  left:0;
  top:0;
  width:var(--particle-size);
  height:var(--particle-size);
  display:grid;
  place-items:center;
  font-size:var(--particle-size);
  line-height:1;
  opacity:0;
  will-change:transform,opacity;
  animation:wikaruThemeParticleBurst .68s cubic-bezier(.2,.72,.2,1) var(--particle-delay) both;
