  68% { opacity:1; }
  100% { transform:translate(-50%,-50%) scale(1); opacity:1; }
}
@keyframes wikaruThemeIconEnter {
  0% { opacity:0; transform:translate(-50%,-50%) scale(.44) rotate(-42deg); }
  52% { opacity:1; transform:translate(-50%,-50%) scale(1.12) rotate(8deg); }
  78% { opacity:1; transform:translate(-50%,-50%) scale(1) rotate(0deg); }
  100% { opacity:0; transform:translate(-50%,-50%) scale(.92) rotate(0deg); }
}
@keyframes wikaruThemeParticleBurst {
  0% {
    opacity:0;
    transform:translate(-50%,-50%) rotate(var(--particle-angle)) translateX(8px) scale(.35);
  }
  28% { opacity:1; }
  100% {
    opacity:0;
    transform:translate(-50%,-50%) rotate(var(--particle-angle)) translateX(var(--particle-distance)) scale(.8);
  }
}
@keyframes wikaruThemeToggleIconSpin {
