  45% { transform:rotate(150deg) scale(.58); opacity:.55; }
  100% { transform:rotate(360deg) scale(1); opacity:1; }
}
@keyframes wikaruThemeContentPulse {
  0% { filter:saturate(1) brightness(1); transform:scale(1); }
  45% { filter:saturate(.88) brightness(.97); transform:scale(.997); }
  100% { filter:saturate(1) brightness(1); transform:scale(1); }
}

::view-transition-old(root),
::view-transition-new(root) {
  animation-duration:.32s;
