  mix-blend-mode:normal;
}
::view-transition-old(root) { animation-name:wikaruThemeViewOld; }
::view-transition-new(root) { animation-name:wikaruThemeViewNew; }
@keyframes wikaruThemeViewOld { to { opacity:.72; } }
@keyframes wikaruThemeViewNew { from { opacity:.82; } }

.loader { z-index:3000!important; }
