/* source-style: wikaru-language-motion-responsive-final */
:root{
  --language-motion-duration:680ms;
  --language-motion-ease:cubic-bezier(.2,.78,.22,1);
}


.language-toggle,
#navLangBtn,
#langToggleDrop,
#homeLangBtn{
  position:relative;
  min-width:0;
  -webkit-tap-highlight-color:transparent;
}
#navLangBtn .nav-lang-globe{
  flex:0 0 auto;
  width:30px;
  height:30px;
  display:grid;
  place-items:center;
  border-radius:50%;
}
#navLangBtn .lang-name,
#navLangBtn .lang-code{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.language-toggle.is-language-switching,
#navLangBtn.is-language-switching,
#langToggleDrop.is-language-switching,
#homeLangBtn.is-language-switching{
  pointer-events:none;
  transform:scale(.95)!important;
}
:is(.language-toggle,#navLangBtn,#langToggleDrop,#homeLangBtn).is-language-switching i{
  animation:wikaruLanguageGlobeSpin .66s var(--language-motion-ease) both;
}

.language-transition-overlay{
  position:fixed;
  inset:0;
  z-index:2450;
  max-width:100vw;
  max-height:100vh;
  max-height:100dvh;
  overflow:hidden;
  pointer-events:none;
  isolation:isolate;
  contain:strict;
  opacity:1;
  transition:opacity .18s ease;
}
.language-transition-overlay.is-fading{opacity:0;}
.language-transition-halo{
  position:absolute;
  left:var(--language-origin-x);
  top:var(--language-origin-y);
  width:174px;
  height:174px;
  border-radius:50%;
  transform:translate(-50%,-50%) scale(.12);
  opacity:0;
  will-change:transform,opacity;
  animation:wikaruLanguageHalo .66s var(--language-motion-ease) both;
}
.language-to-ja .language-transition-halo{
  background:radial-gradient(circle,rgba(141,165,245,.34) 0%,rgba(81,103,184,.18) 38%,transparent 72%);
}
.language-to-id .language-transition-halo{
  background:radial-gradient(circle,rgba(102,214,193,.31) 0%,rgba(71,152,170,.16) 38%,transparent 72%);
}
.language-transition-badge{
  position:absolute;
  left:var(--language-badge-x);
  top:var(--language-badge-y);
  min-width:94px;
  min-height:64px;
  padding:10px 16px;
  border-radius:22px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  transform:translate(-50%,-50%);
  opacity:0;
  color:#fff;
  border:1px solid rgba(255,255,255,.28);
  box-shadow:0 20px 52px rgba(10,20,42,.24),inset 0 1px 0 rgba(255,255,255,.26);
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
  will-change:transform,opacity;
  animation:wikaruLanguageBadgeEnter .68s var(--language-motion-ease) both;
}
.language-transition-badge i{font-size:20px;}
.language-transition-badge strong{
  font-family:var(--jp,"Noto Sans JP",sans-serif);
  font-size:16px;
  line-height:1;
  letter-spacing:-.02em;
  white-space:nowrap;
}
.language-to-ja .language-transition-badge{
  background:linear-gradient(145deg,rgba(64,86,159,.96),rgba(36,59,115,.96));
}
.language-to-id .language-transition-badge{
  background:linear-gradient(145deg,rgba(31,160,139,.96),rgba(36,102,124,.96));
}
.language-transition-glyphs{
  position:absolute;
  left:var(--language-badge-x);
  top:var(--language-badge-y);
  width:1px;
  height:1px;
}
.language-glyph{
  position:absolute;
  left:0;
  top:0;
  display:grid;
  place-items:center;
  width:var(--glyph-size);
  height:var(--glyph-size);
  border-radius:14px;
  font-family:var(--jp,"Noto Sans JP",sans-serif);
  font-size:calc(var(--glyph-size) * .45);
  font-weight:800;
  line-height:1;
  color:#fff;
  opacity:0;
  background:rgba(255,255,255,.14);
  border:1px solid rgba(255,255,255,.22);
  box-shadow:0 12px 32px rgba(12,22,42,.16);
  will-change:transform,opacity;
  animation:wikaruLanguageGlyphFloat .66s var(--language-motion-ease) var(--glyph-delay) both;
}
.language-to-ja .language-glyph{background:rgba(91,117,202,.68);}
.language-to-id .language-glyph{background:rgba(42,167,145,.68);}

html.language-is-changing .page.active,
html.language-is-changing .top-nav,
html.language-is-changing .bottom-nav,
html.language-is-changing .modal.show .modal-card,
html.language-is-changing #userDropdown.show{
  animation:wikaruLanguageContentShift var(--language-motion-duration) ease both;
}

@keyframes wikaruLanguageGlobeSpin{
  0%{transform:rotate(0deg) scale(1);opacity:1;}
  44%{transform:rotate(155deg) scale(.65);opacity:.55;}
  100%{transform:rotate(360deg) scale(1);opacity:1;}
}
@keyframes wikaruLanguageHalo{
  0%{opacity:0;transform:translate(-50%,-50%) scale(.12);}
  42%{opacity:1;}
  100%{opacity:0;transform:translate(-50%,-50%) scale(2.25);}
}
@keyframes wikaruLanguageBadgeEnter{
  0%{opacity:0;transform:translate(-50%,-50%) scale(.65) rotate(-8deg);}
  50%{opacity:1;transform:translate(-50%,-50%) scale(1.08) rotate(3deg);}
  76%{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(0);}
  100%{opacity:0;transform:translate(-50%,-50%) scale(.95) rotate(0);}
}
@keyframes wikaruLanguageGlyphFloat{
  0%{opacity:0;transform:translate(-50%,-50%) rotate(var(--glyph-angle)) translateX(10px) scale(.55);}
  30%{opacity:.92;}
  100%{opacity:0;transform:translate(-50%,-50%) rotate(var(--glyph-angle)) translateX(var(--glyph-distance)) rotate(calc(var(--glyph-angle) * -1)) scale(.88);}
}
@keyframes wikaruLanguageContentShift{
  0%{opacity:1;transform:translateY(0);}
  38%{opacity:.42;transform:translateY(-4px);}
  54%{opacity:.36;transform:translateY(4px);}
  100%{opacity:1;transform:translateY(0);}
}
@keyframes wikaruLanguageViewOld{to{opacity:.3;transform:translateY(-4px);}}
@keyframes wikaruLanguageViewNew{from{opacity:.25;transform:translateY(4px);}}
html.language-is-changing::view-transition-old(root){
  animation:wikaruLanguageViewOld .28s ease both;
  mix-blend-mode:normal;
}
html.language-is-changing::view-transition-new(root){
  animation:wikaruLanguageViewNew .34s ease both;
  mix-blend-mode:normal;
}


