/* source-style: wikaru-time-appendix-style */
body.time-appendix-active #materialGrid.time-appendix-root{
    display:block!important;
    width:100%;
  }
  .time-appendix-root{
    --time-navy:#243B73;
    --time-ink:#071b45;
    --time-soft:#EEF1F8;
    --time-line:rgba(36,59,115,.13);
    --time-card-shadow:0 16px 38px rgba(28,37,25,.09);
  }
  .time-hero{
    position:relative;
    overflow:hidden;
    display:grid;
    grid-template-columns:minmax(0,1.15fr) minmax(330px,.85fr);
    gap:28px;
    padding:34px;
    margin-bottom:24px;
    border:1px solid rgba(255,255,255,.9);
    border-radius:30px;
    background:
      radial-gradient(circle at 95% 8%,rgba(125,181,255,.36),transparent 34%),
      radial-gradient(circle at 8% 92%,rgba(255,211,109,.26),transparent 35%),
      linear-gradient(145deg,rgba(255,255,255,.97),rgba(246,248,255,.86));
    box-shadow:var(--shadow);
  }
  .time-hero::after{
    content:"";
    position:absolute;
    width:260px;
    height:260px;
    right:-115px;
    bottom:-130px;
    border-radius:50%;
    background:rgba(36,59,115,.08);
    pointer-events:none;
  }
  .time-kicker{
    display:inline-flex;
    align-items:center;
    gap:8px;
    padding:8px 13px;
    border-radius:999px;
    color:var(--time-navy);
    background:rgba(233,237,250,.95);
    border:1px solid var(--time-line);
    font-size:12px;
    font-weight:800;
  }
  .time-hero h3{
    margin:16px 0 4px;
    color:var(--time-ink);
    font-family:var(--jp);
    font-size:clamp(32px,4.3vw,56px);
    line-height:1.08;
    letter-spacing:-.045em;
  }
  .time-hero-reading{
    color:var(--time-navy);
    font-family:var(--jp);
    font-weight:700;
    font-size:17px;
  }
  .time-hero-copy>p{
    max-width:730px;
    margin:15px 0 20px;
    color:#58667f;
    font-size:15px;
  }
  .time-hero-actions{
    display:flex;
    flex-wrap:wrap;
    gap:10px;
  }
  .time-hero-stats{
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:11px;
    margin-top:22px;
  }
  .time-stat{
    display:flex;
    align-items:center;
    gap:12px;
    min-height:72px;
    padding:13px;
    border-radius:20px;
    background:rgba(255,255,255,.8);
    border:1px solid var(--time-line);
    box-shadow:0 9px 22px rgba(36,59,115,.06);
  }
  .time-stat i{
    width:42px;
    height:42px;
    display:grid;
    place-items:center;
    flex:0 0 auto;
    border-radius:14px;
    color:var(--time-navy);
    background:var(--time-soft);
  }
  .time-stat strong{
    display:block;
    color:var(--time-ink);
    font-size:22px;
    line-height:1;
  }
  .time-stat span{
    display:block;
    margin-top:4px;
    color:#758198;
    font-size:11px;
    font-weight:700;
  }
  .time-reference-map{
    align-self:stretch;
    display:flex;
    flex-direction:column;
    justify-content:center;
    gap:15px;
    min-height:300px;
    padding:20px;
    border-radius:26px;
    background:linear-gradient(155deg,#fff,#F4F5F0);
    border:1px solid var(--time-line);
    box-shadow:var(--time-card-shadow);
  }
  .time-reference-map h4{
    margin:0;
    text-align:center;
    color:var(--time-ink);
    font-size:16px;
  }
  .time-axis{
    display:grid;
    grid-template-columns:1fr auto 1fr auto 1fr;
    align-items:center;
    gap:7px;
  }
  .time-axis-arrow{
    color:#8b97ab;
    font-size:13px;
  }
  .time-axis-node{
    min-width:0;
    padding:13px 8px;
    text-align:center;
    border-radius:18px;
    background:#fff;
    border:1px solid var(--time-line);
  }
  .time-axis-node.current{
    color:#fff;
    background:linear-gradient(135deg,var(--time-navy),#35549D);
    border-color:transparent;
    box-shadow:0 12px 24px rgba(36,59,115,.22);
  }
  .time-axis-node b{
    display:block;
    font-family:var(--jp);
    font-size:18px;
    line-height:1.25;
  }
  .time-axis-node small{
    display:block;
    margin-top:4px;
    color:#77849b;
    font-size:10px;
    font-weight:700;
  }
  .time-axis-node.current small{color:rgba(255,255,255,.78);}
  .time-map-tip{
    display:flex;
    align-items:flex-start;
    gap:10px;
    margin:0;
    padding:12px 13px;
    border-radius:16px;
    background:#fff8e8;
    color:#76612e;
    font-size:11px;
    line-height:1.55;
    border:1px solid rgba(255,211,109,.55);
  }
  .time-map-tip i{margin-top:2px;color:#b78313;}
  .time-table-section{
    margin-top:22px;
    padding:24px;
    border-radius:28px;
    background:linear-gradient(145deg,rgba(255,255,255,.92),rgba(255,255,255,.72));
    border:1px solid rgba(255,255,255,.88);
    box-shadow:var(--shadow2);
  }
  .time-table-head{
    display:flex;
    align-items:flex-end;
    justify-content:space-between;
    gap:16px;
    margin-bottom:18px;
  }
  .time-table-head h3{
    display:flex;
    align-items:center;
    gap:10px;
    margin:0;
    color:var(--time-ink);
    font-size:22px;
  }
  .time-table-head p{
    margin:5px 0 0;
    font-size:13px;
    line-height:1.5;
  }
  .time-table-count{
    flex:0 0 auto;
    padding:8px 12px;
    border-radius:999px;
    color:var(--time-navy);
    background:var(--time-soft);
    font-size:11px;
    font-weight:800;
  }
  .time-group-grid{
    display:grid;
    grid-template-columns:repeat(3,minmax(0,1fr));
    gap:16px;
    align-items:start;
  }
  .time-column{
    overflow:hidden;
    border-radius:24px;
    background:rgba(248,250,255,.86);
    border:1px solid var(--time-line);
  }
  .time-column-head{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
    min-height:68px;
    padding:14px 16px;
    color:#fff;
    background:linear-gradient(135deg,var(--time-navy),#35549D);
  }
  .time-column[data-group="Pagi"] .time-column-head{
    color:#4e3a05;
    background:linear-gradient(135deg,#ffd36d,#ffe7a7);
  }
  .time-column[data-group="Malam"] .time-column-head{
    background:linear-gradient(135deg,#252d54,#5367a8);
  }
  .time-column[data-group="Minggu"] .time-column-head{
    background:linear-gradient(135deg,#2c7b72,#56b9a8);
  }
  .time-column[data-group="Bulan"] .time-column-head{
    background:linear-gradient(135deg,#7c579f,#b28bd1);
  }
  .time-column[data-group="Tahun"] .time-column-head{
    background:linear-gradient(135deg,#a55546,#db8c75);
  }
  .time-column-title{
    display:flex;
    align-items:center;
    gap:11px;
    min-width:0;
  }
  .time-column-icon{
    width:39px;
    height:39px;
    display:grid;
    place-items:center;
    flex:0 0 auto;
    border-radius:13px;
    background:rgba(255,255,255,.19);
  }
  .time-column[data-group="Pagi"] .time-column-icon{
    background:rgba(255,255,255,.45);
  }
  .time-column-title strong{
    display:block;
    font-size:16px;
    line-height:1.1;
  }
  .time-column-title small{
    display:block;
    margin-top:4px;
    font-family:var(--jp);
    opacity:.82;
    font-size:11px;
  }
  .time-column-count{
    min-width:32px;
    height:32px;
    display:grid;
    place-items:center;
    border-radius:999px;
    background:rgba(255,255,255,.18);
    font-size:11px;
    font-weight:850;
  }
  .time-card-list{
    display:grid;
    gap:12px;
    padding:12px;
  }
  .time-vocab-card{
    overflow:hidden;
    border-radius:20px;
    background:#fff;
    border:1px solid rgba(36,59,115,.11);
    box-shadow:0 9px 22px rgba(36,59,115,.055);
    transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;
  }
  .time-vocab-card:hover{
    transform:translateY(-2px);
    border-color:rgba(36,59,115,.25);
    box-shadow:0 15px 30px rgba(36,59,115,.1);
  }
  .time-image-wrap{
    position:relative;
    overflow:hidden;
    aspect-ratio:16/10;
    background:linear-gradient(135deg,#f4f6fb,#eef6ff);
  }
  .time-vocab-image{
    width:100%;
    height:100%;
    display:block;
    object-fit:cover;
    transition:transform .25s ease;
    cursor:zoom-in;
  }
  .time-vocab-card:hover .time-vocab-image{transform:scale(1.025);}
  .time-vocab-card.image-error .time-image-wrap::after{
    content:"Gambar gagal dimuat";
    position:absolute;
    inset:0;
    display:grid;
    place-items:center;
    color:#758198;
    font-size:12px;
    font-weight:700;
    background:linear-gradient(135deg,#f5f6fa,#eef2f8);
  }
  .time-index{
    position:absolute;
    top:10px;
    left:10px;
    z-index:2;
    min-width:36px;
    height:28px;
    display:grid;
    place-items:center;
    padding:0 9px;
    border-radius:999px;
    color:#fff;
    background:rgba(7,27,69,.78);
    backdrop-filter:blur(8px);
    font-size:10px;
    font-weight:850;
  }
  .time-card-body{padding:15px;}
  .time-word-row{
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    gap:10px;
  }
  .time-word-copy{min-width:0;}
  .time-word-kanji{
    color:var(--time-ink);
    font-family:var(--jp);
    font-size:clamp(20px,2vw,26px);
    font-weight:800;
    line-height:1.25;
    overflow-wrap:anywhere;
  }
  .time-word-kana{
    margin-top:3px;
    color:#5f6d85;
    font-family:var(--jp);
    font-size:12px;
    line-height:1.4;
    overflow-wrap:anywhere;
  }
  .time-card-audio{
    width:39px;
    height:39px;
    display:grid;
    place-items:center;
    flex:0 0 auto;
    border:1px solid rgba(36,59,115,.14);
    border-radius:13px;
    color:var(--time-navy);
    background:#fff;
  }
  .time-card-audio:hover{background:var(--time-soft);}
  .time-romaji{
    margin-top:8px;
    color:var(--time-navy);
    font-size:11px;
    font-weight:800;
    letter-spacing:.01em;
  }
  .time-meaning{
    margin-top:8px;
    color:#33415b;
    font-size:14px;
    font-weight:750;
  }
  .time-example{
    margin-top:13px;
    padding:12px;
    border-radius:16px;
    background:linear-gradient(135deg,#f8f9fc,#f6f3ff);
    border:1px solid rgba(36,59,115,.08);
  }
  .time-example-label{
    display:flex;
    align-items:center;
    gap:6px;
    margin-bottom:7px;
    color:var(--time-navy);
    font-size:9px;
    font-weight:850;
    text-transform:uppercase;
    letter-spacing:.08em;
  }
  .time-example-ja{
    margin:0;
    color:var(--time-ink);
    font-family:var(--jp);
    font-size:13px;
    font-weight:700;
    line-height:1.6;
    user-select:text;
  }
  .time-example-reading{
    margin:5px 0 0;
    color:#63708a;
    font-size:10.5px;
    line-height:1.5;
    font-style:italic;
    user-select:text;
  }
  .time-example-id{
    margin:6px 0 0;
    color:#3d4a62;
    font-size:10.5px;
    line-height:1.5;
    user-select:text;
  }
  .time-note{
    margin-top:10px;
    border-top:1px solid rgba(36,59,115,.09);
  }
  .time-note summary{
    display:flex;
    align-items:center;
    gap:7px;
    padding:10px 0 0;
    color:#536078;
    font-size:10.5px;
    font-weight:800;
    cursor:pointer;
    list-style:none;
  }
  .time-note summary::-webkit-details-marker{display:none;}
  .time-note summary::before{
    content:"+";
    width:20px;
    height:20px;
    display:grid;
    place-items:center;
    border-radius:7px;
    color:var(--time-navy);
    background:var(--time-soft);
    font-size:13px;
  }
  .time-note[open] summary::before{content:"−";}
  .time-note p{
    margin:8px 0 0;
    color:#68758c;
    font-size:10.5px;
    line-height:1.58;
    user-select:text;
  }
  .time-card-actions{
    display:flex;
    align-items:center;
    gap:7px;
    margin-top:12px;
  }
  .time-card-actions .icon-btn{
    width:37px;
    height:37px;
    border-radius:12px;
    box-shadow:none;
  }
  .time-empty{
    padding:38px 18px;
    text-align:center;
    border-radius:24px;
    color:#66728a;
    background:rgba(255,255,255,.7);
    border:1px dashed rgba(36,59,115,.25);
  }
  .time-empty i{
    display:block;
    margin-bottom:10px;
    color:var(--time-navy);
    font-size:30px;
  }
  html[data-theme="dark"] .time-hero,
  html[data-theme="dark"] .time-table-section{
    background:linear-gradient(145deg,rgba(35,42,55,.96),rgba(27,34,48,.88));
    border-color:#394156;
  }
  html[data-theme="dark"] .time-reference-map,
  html[data-theme="dark"] .time-axis-node,
  html[data-theme="dark"] .time-vocab-card,
  html[data-theme="dark"] .time-stat{
