.wk-theme-motion-overlay-v8{
  position:fixed!important;
  inset:0!important;
  z-index:9999!important;
  display:block!important;
  visibility:visible!important;
  overflow:hidden!important;
  pointer-events:none!important;
  isolation:isolate!important;
  contain:strict!important;
  opacity:1;
}
.wk-theme-motion-overlay-v8.is-leaving{
  opacity:0;
  transition:opacity .20s ease!important;
}
.wk-theme-motion-circle-v8{
  position:absolute;
  left:var(--wk8-origin-x);
  top:var(--wk8-origin-y);
  width:var(--wk8-diameter);
  height:var(--wk8-diameter);
  border-radius:50%;
  transform:translate(-50%,-50%) scale(.001);
  transform-origin:center;
  will-change:transform,opacity;
  animation:wk8ThemeCircleReveal .76s cubic-bezier(.18,.82,.22,1) both!important;
}
.wk-theme-motion-overlay-v8.to-dark .wk-theme-motion-circle-v8{
  background:
    radial-gradient(circle at 50% 50%,rgba(126,157,242,.22),transparent 40%),
    linear-gradient(145deg,#111c2a 0%,#0f1722 54%,#09111b 100%);
  box-shadow:0 0 120px rgba(91,116,194,.25);
}
.wk-theme-motion-overlay-v8.to-light .wk-theme-motion-circle-v8{
  background:
    radial-gradient(circle at 50% 50%,rgba(255,220,126,.34),transparent 43%),
    linear-gradient(145deg,#ffffff 0%,#f7f8fa 54%,#edf4ff 100%);
  box-shadow:0 0 120px rgba(255,210,91,.26);
}
.wk-theme-motion-icon-v8{
  position:absolute;
  left:var(--wk8-icon-x);
  top:var(--wk8-icon-y);
  width:74px;
  height:74px;
  display:grid;
  place-items:center;
  border-radius:25px;
  transform:translate(-50%,-50%);
  will-change:transform,opacity;
  animation:wk8ThemeIconMotion .76s cubic-bezier(.2,.8,.2,1) both!important;
  box-shadow:0 18px 50px rgba(0,0,0,.22),inset 0 1px 0 rgba(255,255,255,.35);
}
.wk-theme-motion-icon-v8 i{font-size:30px!important;}
.wk-theme-motion-overlay-v8.to-dark .wk-theme-motion-icon-v8{
  color:#f3f6ff;
  background:linear-gradient(145deg,#7894eb,#364777);
  border:1px solid rgba(221,230,255,.35);
}
.wk-theme-motion-overlay-v8.to-light .wk-theme-motion-icon-v8{
  color:#765400;
  background:linear-gradient(145deg,#fff4b8,#ffcd5b);
  border:1px solid rgba(255,255,255,.76);
}
.wk-theme-motion-particles-v8{
  position:absolute;
  left:var(--wk8-icon-x);
  top:var(--wk8-icon-y);
  width:1px;
  height:1px;
}
.wk-theme-motion-particles-v8 span{
  position:absolute;
  left:0;
  top:0;
  display:grid;
  place-items:center;
  width:var(--wk8-particle-size);
  height:var(--wk8-particle-size);
  font-size:var(--wk8-particle-size);
  line-height:1;
  opacity:0;
  animation:wk8ThemeParticle .66s cubic-bezier(.2,.72,.2,1)
    var(--wk8-particle-delay) both!important;
}
.wk-theme-motion-overlay-v8.to-dark .wk-theme-motion-particles-v8 span{
  color:#dce6ff;
  text-shadow:0 0 12px rgba(156,181,255,.9);
}
.wk-theme-motion-overlay-v8.to-light .wk-theme-motion-particles-v8 span{
  color:#ffc94f;
  text-shadow:0 0 12px rgba(255,201,79,.78);
}
#wk-theme-motion-button-v8,
#themeToggle.wk-theme-switching-v8{
  pointer-events:none!important;
}
#themeToggle.wk-theme-switching-v8 i{
  animation:wk8ThemeButtonSpin .68s cubic-bezier(.2,.8,.2,1) both!important;
}
@keyframes wk8ThemeCircleReveal{
  0%{transform:translate(-50%,-50%) scale(.001);opacity:.96;}
  68%{opacity:1;}
  100%{transform:translate(-50%,-50%) scale(1);opacity:1;}
}
@keyframes wk8ThemeIconMotion{
  0%{opacity:0;transform:translate(-50%,-50%) scale(.42) rotate(-42deg);}
  52%{opacity:1;transform:translate(-50%,-50%) scale(1.12) rotate(8deg);}
  78%{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(0);}
  100%{opacity:0;transform:translate(-50%,-50%) scale(.92) rotate(0);}
}
@keyframes wk8ThemeParticle{
  0%{
    opacity:0;
    transform:translate(-50%,-50%) rotate(var(--wk8-angle))
      translateX(8px) scale(.35);
  }
  28%{opacity:1;}
  100%{
    opacity:0;
    transform:translate(-50%,-50%) rotate(var(--wk8-angle))
      translateX(var(--wk8-distance)) scale(.8);
  }
}
@keyframes wk8ThemeButtonSpin{
  0%{transform:rotate(0) scale(1);opacity:1;}
  45%{transform:rotate(150deg) scale(.58);opacity:.55;}
  100%{transform:rotate(360deg) scale(1);opacity:1;}
}


@media(prefers-reduced-motion:reduce){
  .wk-theme-motion-circle-v8{
    animation-duration:.18s!important;
  }
  .wk-theme-motion-icon-v8,
  .wk-theme-motion-particles-v8 span,
  #themeToggle.wk-theme-switching-v8 i{
    animation:none!important;
  }
  html.wk-theme-changing-v8 body.time-appendix-active .time-appendix-root{
    animation:none!important;
  }
}

