.flashcard.flipped .flash-front,.marker-flash-stage.flipped .marker-flash-front{visibility:hidden!important;opacity:0!important;pointer-events:none!important;}

/* One clean voice control area: voice choices + one microphone action. */
body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-grid{
  grid-template-columns:repeat(2,minmax(0,1fr))!important;
  gap:9px!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-option{
  min-height:68px!important;
  display:grid!important;
  grid-template-columns:34px minmax(0,1fr)!important;
  grid-template-rows:auto auto!important;
  column-gap:9px!important;
  align-items:center!important;
  padding:9px 10px!important;
  border-radius:15px!important;
  text-align:left!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-option > i{
  grid-row:1/3!important;
  width:34px!important;
  height:34px!important;
  display:grid!important;
  place-items:center!important;
  border-radius:11px!important;
  background:var(--wk-primary-soft,#E9EDFA)!important;
  color:var(--wk-primary,#243B73)!important;
  font-size:14px!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-option strong{
  align-self:end!important;
  font-size:12px!important;
  line-height:1.15!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-option small{
  align-self:start!important;
  margin-top:2px!important;
  font-size:9.5px!important;
  line-height:1.25!important;
  white-space:normal!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-option.active > i{
  background:linear-gradient(135deg,#315FAE,#0F766E)!important;
  color:#fff!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-speech-panel{
  grid-template-columns:48px minmax(0,1fr) auto!important;
  align-items:center!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-speech-restart{
  grid-column:auto!important;
  width:auto!important;
  min-width:92px!important;
  min-height:42px!important;
  justify-content:center!important;
  margin:0!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) .marker-side-actions{display:none!important;}
.verb-question-meaning{display:flex!important;align-items:center!important;gap:8px!important;}
.verb-question-meaning > i{color:var(--primary,#243B73)!important;}

@media(max-width:760px){
  body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-grid{grid-template-columns:1fr 1fr!important;}
  body:is(.marker-quiz-active,.duration-quiz-active) .marker-speech-panel{grid-template-columns:46px minmax(0,1fr)!important;}
  body:is(.marker-quiz-active,.duration-quiz-active) .marker-speech-restart{grid-column:1/-1!important;width:100%!important;}
}
@media(max-width:420px){
  body:is(.marker-quiz-active,.duration-quiz-active) .marker-voice-grid{grid-template-columns:1fr!important;}
}

