/* source-style: wikaru-bab31-academic-fields-style */
body.b31-academic-fields-active #materialPage .notice{
    background:linear-gradient(120deg,#eef4ff,#f7f3ff);
    border-color:rgba(36,59,115,.14);
  }
  .b31-academic-material-wrap{
    display:grid;
    gap:24px;
    min-width:0;
  }
  .b31-academic-reference-sheet{
    overflow:hidden;
    padding:26px 28px 28px;
    border:1px solid rgba(36,59,115,.16);
    border-radius:26px;
    background:
      linear-gradient(rgba(255,255,255,.96),rgba(255,255,255,.96)),
      repeating-linear-gradient(0deg,transparent 0,transparent 27px,rgba(36,59,115,.025) 28px);
    box-shadow:0 18px 44px rgba(28,37,25,.08);
  }
  .b31-academic-sheet-head{
    display:flex;
    align-items:flex-end;
    justify-content:space-between;
    gap:18px;
    padding-bottom:18px;
    margin-bottom:18px;
    border-bottom:1px solid rgba(36,59,115,.18);
  }
  .b31-academic-sheet-title{
    display:flex;
    align-items:flex-end;
    gap:15px;
    min-width:0;
  }
  .b31-academic-jp-title{
    position:relative;
    display:inline-block;
    padding-top:15px;
    font-family:var(--jp);
    font-size:32px;
    line-height:1;
    font-weight:850;
    color:#071b45;
    white-space:nowrap;
  }
  .b31-academic-jp-title small{
    position:absolute;
    top:0;
    left:50%;
    transform:translateX(-50%);
    font-size:10px;
    line-height:1;
    letter-spacing:.12em;
    font-weight:750;
    color:#5f6d86;
  }
  .b31-academic-id-title{
    font-size:clamp(22px,2.5vw,31px);
    line-height:1.05;
    font-weight:820;
    color:#071b45;
    letter-spacing:-.035em;
  }
  .b31-academic-sheet-subtitle{
    margin:5px 0 0;
    color:#66728a;
    font-size:13px;
    font-weight:650;
    line-height:1.5;
  }
  .b31-academic-meta{
    display:flex;
    flex-wrap:wrap;
    justify-content:flex-end;
    gap:8px;
  }
  .b31-academic-meta span{
    display:inline-flex;
    align-items:center;
    gap:7px;
    min-height:34px;
    padding:0 11px;
    border-radius:999px;
    background:#f6f8fd;
    border:1px solid rgba(36,59,115,.12);
    color:#4d5870;
    font-size:12px;
    font-weight:800;
    white-space:nowrap;
  }
  .b31-academic-columns{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:0;
  }
  .b31-academic-column{
    display:grid;
    align-content:start;
    gap:0;
    min-width:0;
  }
  .b31-academic-column:first-child{
    padding-right:26px;
    border-right:1px solid rgba(36,59,115,.22);
  }
  .b31-academic-column:last-child{
    padding-left:26px;
  }
  .b31-academic-row{
    display:grid;
    grid-template-columns:minmax(120px,.92fr) minmax(130px,1.08fr);
    gap:16px;
    align-items:center;
    min-height:52px;
    padding:7px 2px;
    border-bottom:1px solid rgba(36,59,115,.07);
  }
  .b31-academic-column .b31-academic-row:last-child{border-bottom:0}
  .b31-academic-term{
    min-width:0;
    display:flex;
    flex-direction:column;
    align-items:flex-start;
    justify-content:center;
    line-height:1.08;
  }
  .b31-academic-reading{
    min-height:11px;
    margin:0 0 2px 1px;
    color:#69758d;
    font-family:var(--jp);
    font-size:9px;
    line-height:1.05;
    font-weight:700;
    letter-spacing:.04em;
  }
  .b31-academic-term strong{
    font-family:var(--jp);
    color:#101b35;
    font-size:18px;
    line-height:1.2;
    font-weight:800;
    overflow-wrap:anywhere;
  }
  .b31-academic-meaning{
    min-width:0;
    color:#34415a;
    font-size:13px;
    line-height:1.42;
    font-weight:600;
    overflow-wrap:anywhere;
  }
  .b31-academic-grid-head{
    display:flex;
    align-items:end;
    justify-content:space-between;
    gap:16px;
    padding:2px 2px 0;
  }
  .b31-academic-grid-head h3{margin:0;font-size:22px}
  .b31-academic-grid-head p{margin:5px 0 0;font-size:13px}
  .b31-academic-count{
    flex:0 0 auto;
    display:inline-flex;
    align-items:center;
    gap:7px;
    padding:8px 12px;
    border-radius:999px;
    background:#eef7ff;
    color:#243B73;
    font-size:12px;
    font-weight:800;
  }
  .b31-academic-vocab-grid{
    display:grid;
    grid-template-columns:repeat(auto-fill,minmax(245px,1fr));
    gap:14px;
    align-items:stretch;
  }
  html[data-theme="dark"] .b31-academic-reference-sheet{
    background:linear-gradient(145deg,#18253b,#1d2b43);
    border-color:rgba(255,255,255,.11);
  }
  html[data-theme="dark"] .b31-academic-jp-title,
  html[data-theme="dark"] .b31-academic-id-title,
  html[data-theme="dark"] .b31-academic-term strong{color:#eef4ff}
  html[data-theme="dark"] .b31-academic-sheet-subtitle,
  html[data-theme="dark"] .b31-academic-reading,
  html[data-theme="dark"] .b31-academic-meaning{color:#b8c4d7}
  html[data-theme="dark"] .b31-academic-meta span{background:#223149;color:#d8e2f2;border-color:rgba(255,255,255,.1)}
  html[data-theme="dark"] .b31-academic-column:first-child{border-color:rgba(255,255,255,.15)}
  html[data-theme="dark"] .b31-academic-row{border-color:rgba(255,255,255,.06)}
  @media(max-width:900px){
    .b31-academic-sheet-head{align-items:flex-start;flex-direction:column}
    .b31-academic-meta{justify-content:flex-start}
  }
  @media(max-width:760px){
    .b31-academic-reference-sheet{padding:19px 18px 20px;border-radius:22px}
    .b31-academic-sheet-title{align-items:flex-end;gap:11px}
    .b31-academic-jp-title{font-size:28px}
    .b31-academic-columns{grid-template-columns:1fr}
    .b31-academic-column:first-child{padding-right:0;border-right:0}
    .b31-academic-column:last-child{padding-left:0;border-top:1px solid rgba(36,59,115,.18);margin-top:6px;padding-top:6px}
    .b31-academic-grid-head{align-items:flex-start;flex-direction:column}
    .b31-academic-vocab-grid{grid-template-columns:1fr}
  }
  @media(max-width:430px){
    .b31-academic-row{grid-template-columns:minmax(110px,.95fr) minmax(0,1.05fr);gap:12px}
    .b31-academic-term strong{font-size:17px}
    .b31-academic-meaning{font-size:12.5px}
  }

