/* source-style: bab38-position-material-reference-style */
body.position-reference-active #materialPage .position-vocab-no-image .vocab-top{gap:0!important}
    body.position-reference-active #materialPage .position-vocab-no-image .vocab-id,
    body.position-reference-active #materialPage .position-vocab-no-image .tag-row{margin-left:0!important}
    body.position-reference-active #materialPage .position-vocab-no-image .vocab-script-block{width:100%!important}

    .position38-reference-overview,
    .position38-learning-guide{display:none}
    body.position-reference-active #materialPage .position38-reference-overview{display:grid!important}
    body.position-reference-active #materialPage .position38-learning-guide{display:grid!important}

    .position38-reference-overview{
      grid-template-columns:minmax(280px,.9fr) minmax(0,1.1fr);
      gap:22px;
      align-items:center;
      margin:22px 0 18px;
      padding:22px;
      border-radius:26px;
      border:1px solid rgba(36,59,115,.13);
      background:linear-gradient(135deg,#f6f8ff 0%,#fff 48%,#f5fbff 100%);
      box-shadow:0 14px 34px rgba(28,37,25,.07);
    }
    .position38-reference-image-button{
      display:grid;place-items:center;width:100%;min-height:300px;padding:10px;border:1px solid #e1e7f1;
      border-radius:20px;background:#fff;cursor:zoom-in;box-shadow:0 10px 24px rgba(28,37,25,.07)
    }
    .position38-reference-image-button img{display:block;width:100%;max-height:480px;object-fit:contain;border-radius:14px;background:#fff}
    .position38-reference-copy{min-width:0}
    .position38-kicker{display:inline-flex;align-items:center;gap:7px;padding:7px 11px;border-radius:999px;background:#E9EDFA;color:#243B73;font-size:12px;font-weight:800}
    .position38-reference-copy h3{font-family:var(--jp);font-size:clamp(27px,3vw,40px);margin:12px 0 7px;color:#10234a}
    .position38-reference-copy p{margin:0;color:#5d6b80;font-weight:560;line-height:1.7}
    .position38-overview-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:15px}
    .position38-overview-chips span{display:inline-flex;align-items:center;gap:6px;padding:7px 10px;border-radius:999px;background:#fff;border:1px solid #e2e7f0;color:#44536b;font-size:11px;font-weight:800}

    .position38-learning-guide{gap:16px;margin:0 0 22px}
    .position38-guide-section{padding:20px;border-radius:24px;border:1px solid #e1e7f0;background:rgba(255,255,255,.92);box-shadow:0 10px 26px rgba(28,37,25,.05)}
    .position38-guide-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:14px}
    .position38-guide-head h3{margin:0;font-size:21px;color:#10234a}
    .position38-guide-head p{margin:4px 0 0;font-size:12.5px;line-height:1.55;color:#6b7890}
    .position38-guide-badge{white-space:nowrap;padding:7px 10px;border-radius:999px;background:#eef3ff;color:#243B73;font-size:11px;font-weight:800}
    .position38-concept-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}
    .position38-concept-card{padding:13px;border-radius:17px;background:linear-gradient(145deg,#fff,#f8faff);border:1px solid #e5e9f1;min-height:112px}
    .position38-concept-card b{display:block;font-family:var(--jp);font-size:20px;color:#17305f}
    .position38-concept-card span{display:block;margin-top:4px;color:#495971;font-size:11px;font-weight:760}
    .position38-concept-card small{display:block;margin-top:6px;color:#778397;font-size:10.5px;line-height:1.45}

    .position38-pattern-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}
    .position38-pattern-card{padding:14px 15px;border-radius:18px;background:#f8faff;border:1px solid #e2e7f0}
    .position38-pattern-card code{display:block;font-family:var(--jp);font-size:14px;font-weight:800;color:#243B73;white-space:normal;background:transparent;padding:0}
    .position38-pattern-card p{margin:6px 0 0;font-size:11.5px;line-height:1.55;color:#64738a}

    .position38-compare-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
    .position38-compare-card{padding:13px;border-radius:17px;background:#fff;border:1px solid #e4e8f0}
    .position38-compare-card strong{display:block;font-family:var(--jp);font-size:17px;color:#10234a}
    .position38-compare-card span{display:block;margin-top:3px;color:#243B73;font-size:11px;font-weight:800}
    .position38-compare-card p{margin:6px 0 0;font-size:10.8px;line-height:1.5;color:#6b7890}

    body.position-reference-active #materialPage .material-toolbar{display:flex!important;visibility:visible!important;pointer-events:auto!important}
    body.position-reference-active #materialPage #materialGrid{margin-top:16px}

    html[data-theme="dark"] .position38-reference-overview,
    html[data-theme="dark"] .position38-guide-section{background:#18243a;border-color:rgba(255,255,255,.10);box-shadow:none}
    html[data-theme="dark"] .position38-reference-image-button,
    html[data-theme="dark"] .position38-overview-chips span,
    html[data-theme="dark"] .position38-concept-card,
    html[data-theme="dark"] .position38-compare-card{background:#131d2e;border-color:rgba(255,255,255,.10)}
    html[data-theme="dark"] .position38-pattern-card{background:#152136;border-color:rgba(255,255,255,.10)}
    html[data-theme="dark"] .position38-reference-copy h3,
    html[data-theme="dark"] .position38-guide-head h3,
    html[data-theme="dark"] .position38-compare-card strong{color:#eef3ff}
    html[data-theme="dark"] .position38-reference-copy p,
    html[data-theme="dark"] .position38-guide-head p,
    html[data-theme="dark"] .position38-concept-card small,
    html[data-theme="dark"] .position38-pattern-card p,
    html[data-theme="dark"] .position38-compare-card p{color:#aebbd0}

    @media(max-width:1050px){
      .position38-reference-overview{grid-template-columns:1fr}
      .position38-reference-image-button{min-height:240px}
      .position38-concept-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
      .position38-compare-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
    }
    @media(max-width:720px){
      .position38-reference-overview,.position38-guide-section{padding:16px;border-radius:21px}
      .position38-reference-image-button{min-height:210px;padding:7px}
      .position38-concept-grid,.position38-pattern-grid,.position38-compare-grid{grid-template-columns:1fr 1fr}
      .position38-guide-head{display:grid}.position38-guide-badge{width:max-content}
    }
    @media(max-width:460px){
      .position38-concept-grid,.position38-pattern-grid,.position38-compare-grid{grid-template-columns:1fr}
    }

/* source-style: bab40-measurement-reference-style */
/* =========================================================
     Bab 40 — 単位・線・形・模様
     Final layout: no tab-switch, no accordion-hide, no nav scroll
     ========================================================= */

  body.measure40-reference-active #materialPage .content-card{
    overflow:visible!important;
  }

  body.measure40-reference-active #materialPage #materialGrid{
    display:block!important;
    width:100%!important;
    min-width:0!important;
    margin-top:0!important;
  }

  body.measure40-reference-active #materialPage .material-toolbar{
    display:grid!important;
    visibility:visible!important;
    pointer-events:auto!important;
    grid-template-columns:minmax(260px,1fr) minmax(170px,220px) minmax(180px,240px)!important;
    gap:10px!important;
    width:100%!important;
    margin:14px 0 18px!important;
    padding:11px!important;
    border:1px solid rgba(36,59,115,.10)!important;
    border-radius:18px!important;
    background:var(--card,#fff)!important;
    box-shadow:0 8px 22px rgba(25,39,70,.05)!important;
  }

  body.measure40-reference-active #materialPage .material-toolbar > *{
    min-width:0!important;
    margin:0!important;
  }

  .measure40-root{
    width:100%;
    min-width:0;
  }

  .measure40-wrap{
    display:grid;
    gap:14px;
    width:100%;
    min-width:0;
    color:var(--text);
  }

  /* Hero */
  .measure40-hero{
    display:grid;
    grid-template-columns:minmax(0,1fr) 210px;
    gap:20px;
    align-items:center;
    padding:20px;
    border:1px solid rgba(36,59,115,.11);
    border-radius:22px;
    background:
      radial-gradient(circle at 92% 7%,rgba(73,115,197,.10),transparent 30%),
      linear-gradient(135deg,#f8faff 0%,#fff 58%,#f8fcff 100%);
    box-shadow:0 12px 30px rgba(25,39,70,.055);
  }
  .measure40-hero-copy{min-width:0}
  .measure40-kicker{
    display:inline-flex;
    align-items:center;
    gap:7px;
    max-width:100%;
    min-height:30px;
    padding:0 10px;
    border-radius:999px;
    background:#edf2ff;
    color:#243B73;
    font-size:10.5px;
    font-weight:850;
  }
  .measure40-hero h3{
    margin:11px 0 7px;
    font-family:var(--jp);
    font-size:clamp(28px,4vw,42px);
    line-height:1.14;
    letter-spacing:-.03em;
    color:#10234a;
  }
  .measure40-hero h3 span{
    display:block;
    margin-top:5px;
    font-family:var(--font);
    font-size:.44em;
    font-weight:760;
    line-height:1.35;
    letter-spacing:-.01em;
    color:#65738a;
  }
  .measure40-hero p{
    margin:0;
    max-width:760px;
    color:#5f6d83;
    font-size:12.5px;
    line-height:1.65;
  }
  .measure40-chiprow{
    display:flex;
    flex-wrap:wrap;
    gap:7px;
    margin-top:14px;
  }
  .measure40-chiprow span{
    display:inline-flex;
    align-items:center;
    gap:6px;
    min-height:29px;
    padding:0 9px;
    border:1px solid #e2e7ef;
    border-radius:999px;
    background:#fff;
    color:#46556c;
    font-size:10px;
    font-weight:800;
  }

  /* Single reference image */
  .measure40-source{
    width:100%;
    max-width:200px;
    margin:0 auto;
    display:grid;
    gap:6px;
    justify-items:center;
  }
  .measure40-source button{
    position:relative;
    display:grid;
    place-items:center;
    width:100%;
    padding:7px;
    border:1px solid #dfe5ee;
    border-radius:17px;
    background:#fff;
    cursor:zoom-in;
    overflow:hidden;
    box-shadow:0 8px 20px rgba(25,39,70,.08);
  }
  .measure40-source img{
    display:block;
    width:auto;
    max-width:100%;
    height:auto;
    max-height:245px;
    object-fit:contain;
    border-radius:11px;
    background:#fff;
  }
  .measure40-zoom-badge{
    position:absolute;
    right:10px;
    bottom:10px;
    display:grid;
    place-items:center;
    width:32px;
    height:32px;
    border-radius:11px;
    background:rgba(15,35,73,.9);
    color:#fff;
    font-size:12px;
    pointer-events:none;
  }
  .measure40-source figcaption{
    color:#78859a;
    font-size:10px;
    line-height:1.35;
    text-align:center;
  }

  /* Navigation wraps instead of horizontal scroll */
  .measure40-nav{
    display:flex;
    flex-wrap:wrap;
    gap:8px;
    width:100%;
    overflow:visible;
    padding:0;
  }
  .measure40-nav button{
    flex:0 0 auto;
    display:inline-flex;
    align-items:center;
    gap:6px;
    min-height:34px;
    padding:0 10px;
    border:1px solid #e1e6ee;
    border-radius:999px;
    background:#fff;
    color:#46556c;
    font:inherit;
    font-size:10px;
    font-weight:800;
    cursor:pointer;
    white-space:nowrap;
  }
  .measure40-nav button:hover{
    border-color:#aebbd0;
    background:#f7f9ff;
    color:#243B73;
  }

  /* Utility panel: converter and calculator visible together */
  .measure40-tool-shell{
    padding:18px;
    border:1px solid rgba(36,59,115,.10);
    border-radius:22px;
    background:#fff;
    box-shadow:0 8px 22px rgba(25,39,70,.04);
  }
  .measure40-tool-head{
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    gap:14px;
    margin-bottom:13px;
  }
  .measure40-tool-head h3{
    margin:0;
    color:#10234a;
    font-size:20px;
    line-height:1.3;
  }
  .measure40-tool-head p{
    margin:4px 0 0;
    max-width:760px;
    color:#6a778c;
    font-size:11.5px;
    line-height:1.5;
  }
  .measure40-tool-panels{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:12px;
  }
  .measure40-tool-panel{
    padding:15px;
    border:1px solid #e2e7ef;
    border-radius:18px;
    background:linear-gradient(145deg,#fff,#fafcff);
  }
  .measure40-tool-panel-title{
    display:flex;
    align-items:center;
    gap:8px;
    margin-bottom:4px;
    color:#17305f;
    font-size:15px;
    font-weight:850;
  }
  .measure40-tool-panel-copy{
    margin:0 0 12px;
    color:#6d798d;
    font-size:10.8px;
    line-height:1.5;
  }

  .measure40-form-grid{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    gap:9px;
  }
  .measure40-field{
    display:grid;
    gap:4px;
    min-width:0;
  }
  .measure40-field.span2{grid-column:span 2}
  .measure40-field.full{grid-column:1/-1}
  .measure40-field label{
    color:#5d6a80;
    font-size:9.8px;
    font-weight:820;
  }
  .measure40-field input,
  .measure40-field select{
    width:100%;
    min-width:0;
    min-height:41px;
    padding:0 10px;
    border:1px solid #dce3ed;
    border-radius:11px;
    background:#fff;
    color:#24304a;
    font:inherit;
    font-size:11.5px;
  }
  .measure40-tool-actions{
    display:flex;
    flex-wrap:wrap;
    gap:7px;
    margin-top:10px;
  }
  .measure40-tool-btn{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    gap:7px;
    min-height:39px;
    padding:0 12px;
    border:0;
    border-radius:11px;
    background:linear-gradient(135deg,#243B73,#35549D);
    color:#fff;
    font:inherit;
    font-size:11px;
    font-weight:820;
    cursor:pointer;
  }
  .measure40-tool-btn.secondary{
    border:1px solid #dce3ed;
    background:#fff;
    color:#243B73;
  }
  .measure40-result{
    margin-top:10px;
    min-height:66px;
    padding:11px 12px;
    border-radius:13px;
    background:#eef4ff;
    color:#30466e;
    font-size:11px;
    line-height:1.5;
  }
  .measure40-result strong{
    display:block;
    margin-bottom:2px;
    color:#102a5c;
    font-size:16px;
  }
  .measure40-result .jp{
    display:block;
    margin-top:4px;
    color:#273858;
    font-family:var(--jp);
    font-weight:760;
  }
  .measure40-result .reading{
    display:block;
    margin-top:2px;
    color:#68768a;
    font-size:10.3px;
  }
  .measure40-hint{
    margin-top:9px;
    padding:9px 10px;
    border:1px solid #efe0ba;
    border-radius:11px;
    background:#fff9e9;
    color:#735819;
    font-size:10px;
    line-height:1.45;
  }
  .measure40-presets{
    display:flex;
    flex-wrap:wrap;
    gap:6px;
    margin-top:9px;
  }
  .measure40-preset{
    min-height:31px;
    padding:0 9px;
    border:1px solid #dfe5ee;
    border-radius:999px;
    background:#fff;
    color:#40506b;
    font:inherit;
    font-size:9.8px;
    font-weight:780;
    cursor:pointer;
  }

  /* Groups all visible */
  .measure40-groups{
    display:grid;
    gap:12px;
    min-width:0;
  }
  .measure40-group{
    min-width:0;
    border:1px solid #e1e6ee;
    border-radius:19px;
    background:#fff;
    padding:14px;
    scroll-margin-top:118px;
    box-shadow:0 6px 18px rgba(25,39,70,.035);
  }
  .measure40-group-head{
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    gap:12px;
    margin-bottom:10px;
  }
  .measure40-group-title{
    display:flex;
    align-items:flex-start;
    gap:10px;
    min-width:0;
  }
  .measure40-group-icon{
    display:grid;
    place-items:center;
    width:38px;
    height:38px;
    border-radius:12px;
    background:#eef3ff;
    color:#243B73;
    flex:0 0 auto;
  }
  .measure40-group-copy{min-width:0}
  .measure40-group-copy h3{
    margin:0;
    color:#10234a;
    font-size:15px;
    line-height:1.3;
  }
  .measure40-group-copy h3 .jp{font-family:var(--jp)}
  .measure40-group-copy p{
    margin:3px 0 0;
    color:#778397;
    font-size:10.2px;
    line-height:1.4;
  }
  .measure40-count{
    white-space:nowrap;
    padding:5px 8px;
    border-radius:999px;
    background:#eef3ff;
    color:#243B73;
    font-size:9.5px;
    font-weight:830;
  }

  .measure40-vocab-grid{
    display:grid;
    grid-template-columns:repeat(3,minmax(0,1fr));
    gap:9px;
  }
  .measure40-vocab-card{
    min-width:0;
    min-height:172px;
    display:flex;
    flex-direction:column;
    padding:12px;
    border:1px solid #e6eaf0;
    border-radius:15px;
    background:linear-gradient(145deg,#fff,#fbfcff);
  }
  .measure40-vocab-card[data-tone="green"]{border-left:3px solid #4caf6b}
  .measure40-vocab-card[data-tone="blue"]{border-left:3px solid #5389dc}
  .measure40-vocab-card[data-tone="purple"]{border-left:3px solid #8d67ca}
  .measure40-vocab-card[data-tone="orange"]{border-left:3px solid #e69b35}
  .measure40-vocab-card[data-tone="rose"]{border-left:3px solid #dd6c86}
  .measure40-vocab-card[data-tone="aqua"]{border-left:3px solid #3aa7a5}
  .measure40-vocab-card[data-tone="slate"]{border-left:3px solid #64748b}
  .measure40-card-top{
    display:flex;
    align-items:flex-start;
    gap:8px;
    min-width:0;
  }
  .measure40-no{
    flex:0 0 auto;
    display:grid;
    place-items:center;
    min-width:26px;
    height:26px;
    padding:0 5px;
    border-radius:8px;
    background:#eef2ff;
    color:#243B73;
    font-size:9px;
    font-weight:850;
  }
  .measure40-symbol{
    flex:0 0 auto;
    display:grid;
    place-items:center;
    min-width:36px;
    min-height:26px;
    padding:2px 6px;
    border:1px solid #e5e8ee;
    border-radius:8px;
    background:#f7f8fb;
    color:#1e345b;
    font-size:10px;
    font-weight:900;
  }
  .measure40-main{min-width:0;flex:1}
  .measure40-jp{
    color:#11264b;
    font-family:var(--jp);
    font-size:16px;
    font-weight:820;
    line-height:1.35;
    overflow-wrap:anywhere;
  }
  .measure40-kana{
    margin-top:2px;
    color:#59677d;
    font-family:var(--jp);
    font-size:10px;
    line-height:1.35;
  }
  .measure40-romaji{
    margin-top:2px;
    color:#243B73;
    font-size:9.8px;
    font-weight:810;
    overflow-wrap:anywhere;
  }
  .measure40-meaning{
    margin:8px 0 7px;
    color:#46536a;
    font-size:11.7px;
    font-weight:660;
    line-height:1.4;
  }
  .measure40-tags{
    display:flex;
    flex-wrap:wrap;
    gap:4px;
  }
  .measure40-tags span{
    padding:4px 6px;
    border-radius:999px;
    background:#eef2f8;
    color:#536078;
    font-size:8.6px;
    font-weight:800;
  }
  .measure40-tags .part{background:#e9f7ff;color:#1e6787}
  .measure40-tags .trans{background:#fff3d7;color:#895e07}
  .measure40-actions{
    display:flex;
    gap:5px;
    margin-top:auto;
    padding-top:9px;
  }
  .measure40-actions .icon-btn{
    width:33px;
    height:33px;
    border-radius:10px;
    box-shadow:none;
  }

  /* Dark mode */
  html[data-theme="dark"] body.measure40-reference-active #materialPage .material-toolbar,
  html[data-theme="dark"] .measure40-hero,
  html[data-theme="dark"] .measure40-tool-shell,
  html[data-theme="dark"] .measure40-tool-panel,
  html[data-theme="dark"] .measure40-group{
    background:#18243a!important;
    border-color:rgba(255,255,255,.10)!important;
    box-shadow:none!important;
  }
  html[data-theme="dark"] .measure40-vocab-card{
    background:#131d2e;
    border-color:rgba(255,255,255,.09);
  }
  html[data-theme="dark"] .measure40-source button,
  html[data-theme="dark"] .measure40-chiprow span,
  html[data-theme="dark"] .measure40-nav button,
  html[data-theme="dark"] .measure40-field input,
  html[data-theme="dark"] .measure40-field select,
  html[data-theme="dark"] .measure40-tool-btn.secondary,
  html[data-theme="dark"] .measure40-preset{
    background:#131d2e;
    border-color:rgba(255,255,255,.11);
    color:#e8eef8;
  }
  html[data-theme="dark"] .measure40-hero h3,
  html[data-theme="dark"] .measure40-tool-head h3,
  html[data-theme="dark"] .measure40-group-copy h3,
  html[data-theme="dark"] .measure40-jp{
    color:#eef3ff;
  }
  html[data-theme="dark"] .measure40-hero p,
  html[data-theme="dark"] .measure40-tool-head p,
  html[data-theme="dark"] .measure40-group-copy p,
  html[data-theme="dark"] .measure40-meaning{
    color:#aebbd0;
  }

  /* Responsive */
  @media(max-width:1100px){
    body.measure40-reference-active #materialPage .material-toolbar{
      grid-template-columns:1fr 1fr!important;
    }
    body.measure40-reference-active #materialPage .material-toolbar .material-search-box{
      grid-column:1/-1!important;
    }
    .measure40-tool-panels{grid-template-columns:1fr}
    .measure40-form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
    .measure40-field.span2{grid-column:span 1}
    .measure40-vocab-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  }
  @media(max-width:820px){
    .measure40-hero{
      grid-template-columns:1fr;
      gap:15px;
      padding:16px;
    }
    .measure40-source{max-width:230px}
  }
  @media(max-width:720px){
    body.measure40-reference-active #materialPage .material-toolbar{
      grid-template-columns:1fr!important;
      padding:9px!important;
      border-radius:15px!important;
    }
    .measure40-wrap{gap:11px}
    .measure40-tool-shell{padding:13px;border-radius:18px}
    .measure40-tool-head{display:grid}
    .measure40-form-grid{grid-template-columns:1fr}
    .measure40-field.full,
    .measure40-field.span2{grid-column:auto}
    .measure40-group{padding:12px}
    .measure40-group-head{display:grid}
    .measure40-vocab-grid{grid-template-columns:1fr}
    .measure40-nav{gap:6px}
    .measure40-nav button{
      font-size:9.6px;
      padding:0 9px;
    }
  }

/* source-style: bab41-reference-useful-style */
.useful41-wrap{
      width:min(1180px,100%); margin:0 auto; display:grid; gap:24px;
    }
    .useful41-hero{
      display:grid; grid-template-columns:minmax(0,1.06fr) minmax(340px,.94fr); gap:26px; align-items:start;
      padding:32px; border-radius:30px;
      background:linear-gradient(135deg,#fff9f1 0%,#f6f8ff 56%,#f4fff9 100%);
      border:1px solid rgba(36,59,115,.12); box-shadow:0 16px 40px rgba(28,37,25,.08); overflow:hidden;
    }
    .useful41-hero-copy{display:flex;flex-direction:column;justify-content:center;min-width:0;padding:4px 0}
    .useful41-kicker{
      display:inline-flex;align-items:center;gap:8px;align-self:flex-start;padding:8px 12px;border-radius:999px;
      background:#E9EDFA;color:#243B73;font-size:11px;font-weight:800;letter-spacing:.01em
    }
    .useful41-hero h3{font-size:clamp(34px,4.2vw,54px);margin:14px 0 10px;color:#071b45;line-height:1.05;letter-spacing:-.035em}
    .useful41-hero h3 span{display:block;font-family:var(--font);font-size:.42em;line-height:1.25;color:#66728a;margin-top:8px;letter-spacing:-.02em}
    .useful41-lead{margin:0;max-width:64ch;color:#536078;font-size:14.5px;line-height:1.75}
    .useful41-focus{
      display:flex;gap:12px;align-items:flex-start;margin-top:18px;padding:14px 16px;border-radius:18px;
      background:rgba(255,255,255,.76);border:1px solid rgba(36,59,115,.11);color:#4d5971;font-size:12.5px;line-height:1.6
    }
    .useful41-focus i{width:30px;height:30px;display:grid;place-items:center;flex:0 0 30px;border-radius:11px;background:#E9EDFA;color:#243B73;margin-top:1px}
    .useful41-focus strong{color:#243B73}
    .useful41-stats{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
    .useful41-stat{padding:8px 11px;border-radius:999px;background:#fff;border:1px solid #e5e8f1;color:#40506c;font-size:11px;font-weight:800;white-space:nowrap}
    .useful41-stat.no-quiz{background:#f6f7fa;color:#6b7382}

    .useful41-source{margin:0;padding:12px;border-radius:24px;background:#fff;border:1px solid #e5e8f1;box-shadow:0 14px 30px rgba(28,37,25,.08);position:relative}
    .useful41-source-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:2px 2px 10px;flex-wrap:wrap}
    .useful41-source-badge{position:static;display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border-radius:999px;background:#eef1fa;color:#243B73;font-size:10px;font-weight:800}
    .useful41-source-full{display:inline-flex;align-items:center;gap:6px;color:#243B73;font-size:10.5px;font-weight:800;text-decoration:none;white-space:nowrap}
    .useful41-source-full:hover{text-decoration:underline}
    .useful41-source-link{display:block;border-radius:16px;overflow:hidden;background:#fff;outline:none}
    .useful41-source-link:focus-visible{box-shadow:0 0 0 4px rgba(36,59,115,.17)}
    .useful41-source img{width:100%;max-height:560px;object-fit:contain;border-radius:16px;background:#fff;display:block;transition:transform .2s ease}
    .useful41-source-link:hover img{transform:scale(1.012)}
    .useful41-source figcaption{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:11px;padding:0 2px;font-size:11px;color:#6c778d;line-height:1.45}
    .useful41-source figcaption a{color:#243B73;font-weight:800;text-decoration:none;white-space:nowrap}

    .useful41-panel{padding:28px;border-radius:27px;background:rgba(255,255,255,.94);border:1px solid rgba(36,59,115,.11);box-shadow:0 12px 32px rgba(28,37,25,.065)}
    .useful41-panel-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-bottom:18px}
    .useful41-eyebrow{display:inline-flex;align-items:center;gap:7px;margin-bottom:7px;color:#243B73;font-size:10px;font-weight:850;text-transform:uppercase;letter-spacing:.08em}
    .useful41-panel h3{margin:0;font-size:clamp(22px,2.4vw,28px);line-height:1.2;letter-spacing:-.025em;color:#071b45}
    .useful41-panel-head p{margin:6px 0 0;max-width:72ch;font-size:12.5px;line-height:1.6;color:#69758d}
    .useful41-count-note{font-size:11px;font-weight:750;color:#7a8498;white-space:nowrap}

    .useful41-search{
      display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:11px;border-radius:19px;background:#f8faff;border:1px solid #e9edf5;margin-bottom:16px
    }
    .useful41-searchbox{position:relative;flex:1 1 320px;min-width:220px}
    .useful41-searchbox i{position:absolute;left:15px;top:50%;transform:translateY(-50%);color:#7c879b;font-size:13px;pointer-events:none}
    .useful41-search input{width:100%;min-height:46px;border:1px solid #dbe2f3;border-radius:14px;padding:0 15px 0 41px;background:#fff;color:#24304a;outline:none;font-size:13px}
    .useful41-search input:focus{border-color:rgba(36,59,115,.5);box-shadow:0 0 0 4px rgba(36,59,115,.08)}
    .useful41-filter{border:1px solid #dbe2f3;background:#fff;color:#536078;border-radius:999px;padding:0 13px;min-height:40px;font-size:11px;font-weight:800;transition:.18s ease}
    .useful41-filter:hover{border-color:rgba(36,59,115,.35);color:#243B73}
    .useful41-filter.active{background:#243B73;color:#fff;border-color:#243B73;box-shadow:0 8px 18px rgba(36,59,115,.16)}

    .useful41-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:stretch}
    .useful41-card{
      height:100%;display:flex;flex-direction:column;padding:18px;border:1px solid #e3e7ef;border-top:3px solid #cfd9f4;border-radius:20px;background:#fff;
      box-shadow:0 8px 20px rgba(28,37,25,.045);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;min-width:0
    }
    .useful41-card[data-section="Bacaan"]{border-top-color:#e9ba54}
    .useful41-card[data-section="Percakapan"]{border-top-color:#53c7a3}
    .useful41-card:hover{transform:translateY(-2px);box-shadow:0 13px 28px rgba(28,37,25,.075);border-color:#d8deea}
    .useful41-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
    .useful41-card-index{display:inline-flex;align-items:center;margin-bottom:7px;color:#8a94a7;font-size:9px;font-weight:850;letter-spacing:.08em}
    .useful41-card .jp-term{font-family:var(--jp);font-size:22px;font-weight:800;color:#071b45;line-height:1.3;overflow-wrap:anywhere}
    .useful41-reading{font-family:var(--jp);font-size:11px;color:#6e7a91;margin-top:4px;line-height:1.35}
    .useful41-romaji{font-size:11px;color:#243B73;font-weight:800;margin-top:3px;overflow-wrap:anywhere}
    .useful41-card .icon-btn{width:38px;height:38px;border-radius:13px;box-shadow:none;flex:0 0 38px;background:#f8faff}
    .useful41-actions{display:flex;align-items:center;gap:8px;margin-top:auto;padding-top:12px;border-top:1px solid #edf0f5}
    .useful41-actions .icon-btn{width:40px;height:40px;flex:0 0 40px}
    .useful41-actions .icon-btn[data-u41-speak]{color:#243B73;background:#eef3ff;border-color:#dce5f5}
    .useful41-actions .icon-btn[data-u41-example]{color:#b44759;background:#fff1f4;border-color:#f1d6dc}
    .useful41-actions .icon-btn[data-u41-note]{color:#8a6814;background:#fff9e8;border-color:#efe2ba}
    .useful41-actions .icon-btn:hover{transform:translateY(-1px)}
    .useful41-meaning{margin:13px 0 10px;color:#2f3d59;font-size:14px;font-weight:700;line-height:1.5}
    .useful41-tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}
    .useful41-tag{padding:5px 8px;border-radius:999px;background:#eef1fa;color:#243B73;font-size:9.5px;font-weight:800;line-height:1.2}
    .useful41-tag.reading{background:#fff4d8;color:#8a5a00}.useful41-tag.talk{background:#e9fbf5;color:#148060}.useful41-tag.trans{background:#ffeaf0;color:#bd3158}
    .useful41-patterns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
    .useful41-pattern{padding:16px;border-radius:18px;border:1px solid #e5e8f1;background:linear-gradient(145deg,#fff,#f9fbff)}
    .useful41-pattern b{font-family:var(--jp);font-size:17px;color:#071b45}.useful41-pattern-title{font-weight:800;color:#40506c;margin-top:5px;font-size:12px}
    .useful41-pattern p{margin:6px 0 0;font-size:11px;line-height:1.6;color:#66728a}

    .useful41-extra-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
    .useful41-extra{padding:14px;border:1px solid #e5e8f1;border-radius:17px;background:#fff;min-width:0}
