/* source-style: wikaru-v6-fix-and-polish */
:root{
  --wk-paper:#F7F7F2;
  --wk-paper-2:#EFF1EB;
  --wk-surface:#FFFFFF;
  --wk-surface-soft:#F4F5F0;
  --wk-ink:#171917;
  --wk-muted:#68706B;
  --wk-line:#DFE3DA;
  --wk-navy:#243B73;
  --wk-navy-2:#35549D;
  --wk-navy-soft:#E9EDFA;
  --wk-red:#E84B3C;
  --wk-red-soft:#FCECE9;
  --wk-matcha:#63785D;
  --wk-matcha-soft:#EBF0E8;
  --wk-amber:#B57A25;
  --wk-amber-soft:#FFF3D9;
  --wk-teal:#387B75;
  --wk-teal-soft:#E7F3F1;
  --wk-shadow:0 14px 34px rgba(28,37,25,.08);
}
body{
  background:
    radial-gradient(circle at 11% 8%,rgba(36,59,115,.08),transparent 28%),
    radial-gradient(circle at 90% 10%,rgba(232,75,60,.06),transparent 25%),
    radial-gradient(circle at 82% 87%,rgba(99,120,93,.07),transparent 30%),
    linear-gradient(180deg,#F7F7F2 0%,#F2F3ED 52%,#ECEEE7 100%)!important;
}

.user-btn{
  min-height:52px!important;
  padding:5px 10px 5px 6px!important;
  gap:9px!important;
  border-radius:18px!important;
  background:rgba(255,255,255,.92)!important;
  border:1px solid rgba(36,59,115,.12)!important;
  box-shadow:0 10px 26px rgba(28,37,25,.07)!important;
}
.wikaru-user-avatar{
  --avatar-a:#243B73;
  --avatar-b:#35549D;
  width:40px;height:40px;flex:0 0 40px;
  display:grid;place-items:center;position:relative;
  border-radius:14px;
  color:#fff;
  background:linear-gradient(145deg,var(--avatar-a),var(--avatar-b));
  box-shadow:0 8px 18px color-mix(in srgb,var(--avatar-a) 24%,transparent);
  overflow:hidden;
}
.wikaru-user-avatar::before{
  content:"";position:absolute;inset:1px;border:1px solid rgba(255,255,255,.25);border-radius:13px;pointer-events:none;
}
.wikaru-user-avatar i{font-size:16px;position:relative;z-index:1;transform:none!important;}
.wikaru-user-avatar small{
  position:absolute;right:3px;bottom:2px;z-index:2;
  width:15px;height:15px;display:grid;place-items:center;border-radius:6px;
  background:rgba(255,255,255,.18);color:#fff;font-size:8px;font-weight:800;line-height:1;
}
.wikaru-user-copy{display:flex;flex-direction:column;align-items:flex-start;min-width:0;line-height:1.1;}
.wikaru-user-copy>#userMenuText{max-width:110px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px!important;font-weight:720!important;color:var(--wk-ink);}
.wikaru-user-copy>#userRoleText{margin-top:3px;color:var(--wk-muted);font-size:9.5px;font-weight:650;letter-spacing:.02em;}
.user-chevron{margin-left:1px;color:#89938D;font-size:10px;transition:transform .2s ease;}
.user-btn[aria-expanded="true"] .user-chevron,.user-menu:has(.dropdown.show) .user-chevron{transform:rotate(180deg);}

.modal{
  background:rgba(17,24,21,.48)!important;
  backdrop-filter:blur(12px) saturate(1.06)!important;
}
.modal-card{
  background:linear-gradient(180deg,rgba(255,255,255,.99),rgba(249,250,246,.99))!important;
  border:1px solid rgba(36,59,115,.10)!important;
  box-shadow:0 34px 90px rgba(19,28,22,.22)!important;
}
#loginModal .login-card{
  width:min(650px,calc(100% - 24px))!important;
  padding:30px!important;
  border-radius:28px!important;
}
.login-head{display:flex;align-items:center;gap:15px!important;padding-right:48px;}
.login-icon{
  width:58px!important;height:58px!important;border-radius:18px!important;
  display:grid!important;place-items:center!important;
  background:linear-gradient(145deg,var(--wk-navy),var(--wk-navy-2))!important;
  color:#fff!important;box-shadow:0 12px 26px rgba(36,59,115,.18)!important;
}
.login-head h2{font-size:30px!important;letter-spacing:-.045em!important;}
.login-head p{margin:5px 0 0!important;color:var(--wk-muted)!important;}
.wikaru-login-preview{
  display:flex;align-items:center;gap:13px;
  margin:20px 0 17px;padding:13px 15px;border-radius:18px;
  background:linear-gradient(135deg,var(--wk-navy-soft),#F5F7FB);
  border:1px solid rgba(36,59,115,.10);
}
.wikaru-login-preview > .wikaru-user-avatar{
  width:46px;height:46px;flex:0 0 46px;border-radius:16px;
  display:grid;place-items:center;margin-top:0;
  color:#fff;font-size:inherit;
}
.wikaru-login-preview > .wikaru-user-avatar i{
  position:absolute;inset:0;z-index:1;
  display:grid;place-items:center;
  font-size:18px;line-height:1;
  transform:translate(-.5px,-.5px)!important;
}
.wikaru-login-preview > .wikaru-user-avatar small{
  right:3px;bottom:3px;margin:0;
  color:#fff;font-size:8px;line-height:1;
}
.wikaru-login-preview > div{min-width:0;}
.wikaru-login-preview > div > strong{display:block;color:var(--wk-ink);font-size:14px;}
.wikaru-login-preview > div > span{display:block;margin-top:3px;color:var(--wk-muted);font-size:11px;}
.pretty-field,.login-dynamic{padding:15px;border-radius:18px;background:#fff;border:1px solid var(--wk-line);}
.pretty-field+.login-dynamic,.login-dynamic+.login-dynamic{margin-top:12px;}
.field-shell{border-radius:13px!important;background:var(--wk-surface-soft)!important;border:1px solid transparent!important;}
.field-shell:focus-within{background:#fff!important;border-color:rgba(36,59,115,.28)!important;box-shadow:0 0 0 4px rgba(36,59,115,.07)!important;}
.field-label{color:var(--wk-ink)!important;font-size:12px!important;}
.login-actions{padding-top:18px!important;border-top:1px solid var(--wk-line);margin-top:18px;}

#setupModal .modal-card,#quizSettingsModal .modal-card{border-radius:28px!important;}
#setupModal .modal-title .kana-icon,#quizSettingsModal .modal-title .kana-icon{
  width:64px!important;height:64px!important;border-radius:20px!important;
  background:linear-gradient(145deg,var(--wk-navy),var(--wk-navy-2))!important;
  box-shadow:0 14px 28px rgba(36,59,115,.18)!important;
  overflow:hidden;
}
#setupModal .modal-title .kana-icon svg,#quizSettingsModal .modal-title .kana-icon svg{width:42px;height:42px;display:block;}
.setup-progress{
  background:linear-gradient(135deg,#F5F7FC,#F3F5EF)!important;
  border-color:rgba(36,59,115,.10)!important;
  border-radius:17px!important;
}
.setup-progress-top{color:var(--wk-navy)!important;}
.setup-progress-line{background:#E4E9F3!important;height:7px!important;}
.setup-progress-line span{background:linear-gradient(90deg,var(--wk-navy),#6482D1)!important;}
.option-grid{gap:11px!important;}
.option-card.icon-option,.login-group-card{
  --option-accent:var(--wk-navy);
  --option-soft:var(--wk-navy-soft);
  min-height:82px!important;
  display:grid!important;grid-template-columns:48px minmax(0,1fr)!important;align-items:center!important;gap:13px!important;
  padding:14px!important;border-radius:17px!important;
  background:linear-gradient(180deg,#FFFFFF,#FAFBF7)!important;
  border:1px solid var(--wk-line)!important;
  color:var(--wk-ink)!important;
  box-shadow:none!important;
  text-align:left!important;
}
.option-card.icon-option:hover,.login-group-card:hover{
  transform:translateY(-2px)!important;border-color:color-mix(in srgb,var(--option-accent) 28%,var(--wk-line))!important;
  box-shadow:0 12px 24px rgba(28,37,25,.07)!important;
}
.option-card.icon-option.active,.login-group-card.active{
  background:linear-gradient(135deg,var(--option-soft),#fff)!important;
  border-color:color-mix(in srgb,var(--option-accent) 38%,var(--wk-line))!important;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--option-accent) 8%,transparent)!important;
}
.option-soft-icon,.login-group-card>span,.wikaru-category-icon{
  width:46px!important;height:46px!important;display:grid!important;place-items:center!important;
  border-radius:15px!important;background:var(--option-soft)!important;color:var(--option-accent)!important;
  font-size:17px!important;border:1px solid color-mix(in srgb,var(--option-accent) 10%,transparent)!important;
}
.option-card.icon-option.active .option-soft-icon,.login-group-card.active>span{
  background:var(--option-accent)!important;color:#fff!important;
}
.option-card.icon-option>div,.login-group-card>div{min-width:0!important;}
.option-card.icon-option>div>span:not(.option-soft-icon),.login-group-card strong{display:block;color:var(--wk-ink)!important;font-size:13px!important;font-weight:720!important;line-height:1.25;}
.option-card.icon-option small,.login-group-card small{display:block;margin-top:5px!important;color:var(--wk-muted)!important;font-size:10.5px!important;font-weight:500!important;line-height:1.4;}
.category-button,.check-pill{
  --option-accent:var(--wk-navy);--option-soft:var(--wk-navy-soft);
  min-height:46px!important;border-radius:14px!important;background:#fff!important;border:1px solid var(--wk-line)!important;color:var(--wk-ink)!important;
  box-shadow:none!important;padding:7px 11px!important;
}
.category-button>span{display:flex!important;align-items:center!important;gap:8px!important;}
.category-button i{color:var(--option-accent)!important;}
.category-button.active,.check-pill:has(input:checked){background:var(--option-soft)!important;color:var(--option-accent)!important;border-color:color-mix(in srgb,var(--option-accent) 28%,var(--wk-line))!important;}
.modal-footer{background:linear-gradient(180deg,rgba(255,255,255,.72),#fff 34%)!important;border-color:var(--wk-line)!important;box-shadow:none!important;}

.metric.timer-metric{
  position:relative!important;overflow:hidden!important;
  background:linear-gradient(180deg,#FFFFFF,#FAFBF7)!important;
  border:1px solid rgba(36,59,115,.10)!important;
  box-shadow:0 11px 26px rgba(28,37,25,.06)!important;
}
.metric.timer-metric::before{left:0!important;right:0!important;top:0!important;bottom:auto!important;width:auto!important;height:3px!important;background:linear-gradient(90deg,var(--wk-navy),#6482D1)!important;opacity:1!important;}
.timer-track{height:7px;margin:9px 0 12px;border-radius:999px;background:#E6EAF2;overflow:hidden;position:relative;}
.timer-fill{height:100%;width:100%;border-radius:inherit;background:linear-gradient(90deg,var(--wk-navy),#6482D1);transition:width .5s cubic-bezier(.22,1,.36,1),background .2s ease;position:relative;}
.timer-dot{position:absolute;right:0;top:50%;width:13px;height:13px;transform:translate(50%,-50%);border-radius:50%;background:#fff;border:2px solid rgba(36,59,115,.28);box-shadow:0 3px 8px rgba(36,59,115,.16);}
#timerText{font-size:29px!important;letter-spacing:-.045em!important;min-height:35px!important;color:var(--wk-ink)!important;}
#timerText.timer-tick{animation:wkTimerTick .38s cubic-bezier(.16,1,.3,1)!important;}
.timer-metric.timer-warning::before,.timer-metric.timer-warning .timer-fill{background:linear-gradient(90deg,#B57A25,#D6A54D)!important;}
