/* source-style: wikaru-learning-journey-home */
:root{
  --home-primary:#243B73;
  --home-primary-dark:#182A58;
  --home-primary-soft:#E9EDFA;
  --home-background:#F7F7F2;
  --home-surface:#FFFFFF;
  --home-surface-secondary:#F1F3F8;
  --home-text:#111827;
  --home-muted:#667085;
  --home-accent:#E84B3C;
  --home-success:#23A77A;
  --home-warning:#E7A938;
  --home-danger:#DF4968;
  --home-border:#E2E6EF;
  --home-shadow:0 18px 44px rgba(23,34,59,.08);
  --home-shadow-soft:0 8px 24px rgba(23,34,59,.055);
  --home-radius-xl:28px;
  --home-radius-lg:22px;
  --home-radius-md:16px;
  --home-ease:cubic-bezier(.2,.8,.2,1);
}
body{
  background:var(--home-background);
}
body::before{
  background:linear-gradient(180deg,rgba(36,59,115,.028),transparent 360px);
}
.top-nav{
  height:76px;
  background:rgba(255,255,255,.94);
  border-bottom:1px solid var(--home-border);
  box-shadow:0 6px 24px rgba(17,24,39,.045);
  backdrop-filter:blur(16px);
}
.app{padding-top:88px;}
.nav-inner{width:min(1320px,calc(100% - 40px));gap:26px;}
.brand{min-width:210px;gap:12px;}
.brand-icon{width:46px;height:46px;border-radius:15px;box-shadow:none;color:var(--home-primary);background:transparent;}
.brand-copy strong{color:var(--home-text);font-size:18px;}
.brand-copy small{color:var(--home-muted);}
.nav-links{gap:8px;}
.nav-link{
  min-height:44px;
  padding:0 15px;
  border-radius:12px;
  color:#596579;
  font-size:14px;
  font-weight:700;
}
.nav-link::after{display:none;}
.nav-link:hover{background:var(--home-surface-secondary);color:var(--home-primary);}
.nav-link.active{background:var(--home-primary-soft);color:var(--home-primary);}
.nav-actions{gap:10px;}
.nav-lang-btn,.user-btn{
  min-height:46px;
  border:1px solid var(--home-border);
  background:var(--home-surface);
  box-shadow:none;
}
.nav-lang-btn{border-radius:14px;padding:0 12px;}
.nav-lang-btn .lang-code{background:var(--home-primary);box-shadow:none;}
.user-btn{border-radius:14px;padding:0 12px;}
.dropdown{
  top:56px;
  min-width:245px;
  padding:8px;
  border:1px solid var(--home-border);
  border-radius:18px;
  background:var(--home-surface);
  box-shadow:var(--home-shadow);
}
.dropdown .drop-item,
.dropdown .theme-toggle,
.dropdown .nav-fiction-toggle{
  width:100%;
  min-height:46px;
  margin:0;
  padding:0 12px;
  display:flex;
  align-items:center;
  justify-content:flex-start;
  gap:11px;
  border:0;
  border-radius:12px;
  background:transparent;
  color:#4B5565;
  box-shadow:none;
  font-size:13px;
  font-weight:700;
  text-align:left;
}
.dropdown .drop-item:hover,
.dropdown .theme-toggle:hover,
.dropdown .nav-fiction-toggle:hover{background:var(--home-surface-secondary);color:var(--home-primary);transform:none;}
.dropdown .theme-toggle span{display:inline;}
.dropdown .nav-fiction-toggle .fiction-state{margin-left:auto;padding:4px 8px;border-radius:999px;background:var(--home-surface-secondary);color:var(--home-muted);font-size:10px;}
.dropdown .nav-fiction-toggle.active .fiction-state{background:#E4F7F0;color:#15775A;}

.home-page{
  width:min(1320px,calc(100% - 40px));
  padding:28px 0 56px;
}
.home-dashboard{display:grid;gap:24px;}
.home-header{display:flex;align-items:flex-end;justify-content:space-between;gap:28px;padding:4px 2px 2px;}
.home-heading-copy{max-width:760px;}
.home-eyebrow,.home-card-label{
  display:inline-flex;
  align-items:center;
  gap:8px;
  color:var(--home-primary);
  font-size:12px;
  font-weight:750;
  letter-spacing:.015em;
}
.home-eyebrow-dot{width:8px;height:8px;border-radius:50%;background:var(--home-accent);box-shadow:0 0 0 5px rgba(232,75,60,.10);}
.home-header h1{
  margin:10px 0 6px;
  max-width:780px;
  color:var(--home-text);
  font-size:clamp(34px,3.4vw,52px);
  line-height:1.08;
  letter-spacing:-.045em;
  text-wrap:balance;
}
.home-header p{margin:0;color:var(--home-muted);font-size:15px;line-height:1.65;}
.home-header-actions{display:flex;align-items:center;gap:12px;}
.home-streak,.home-profile-shortcut{
  min-height:58px;
  display:flex;
  align-items:center;
  gap:11px;
  border:1px solid var(--home-border);
  border-radius:17px;
  background:var(--home-surface);
  color:var(--home-text);
  box-shadow:var(--home-shadow-soft);
}
.home-streak{padding:8px 15px 8px 9px;}
.home-streak-icon,.home-profile-avatar{
  width:40px;height:40px;display:grid;place-items:center;flex:0 0 auto;border-radius:13px;
}
.home-streak-icon{background:#FFF0E9;color:var(--home-accent);}
.home-streak span:last-child,.home-profile-copy{display:grid;gap:2px;min-width:0;}
.home-streak strong,.home-profile-copy strong{color:var(--home-text);font-size:14px;line-height:1.1;}
.home-streak small,.home-profile-copy small{color:var(--home-muted);font-size:10px;line-height:1.25;}
.home-profile-shortcut{padding:8px 12px 8px 9px;min-width:210px;text-align:left;}
.home-profile-avatar{background:var(--home-primary-soft);color:var(--home-primary);}
.home-profile-shortcut>i{margin-left:auto;color:#9AA4B3;font-size:11px;}
.home-profile-shortcut:hover{border-color:#C7D0E0;transform:translateY(-1px);}

.home-main-grid{
  display:grid;
  grid-template-columns:repeat(12,minmax(0,1fr));
  grid-template-areas:
    "continue continue continue continue continue continue continue continue vocab vocab vocab vocab"
    "stats stats stats stats stats stats stats stats stats stats stats stats"
    "quick quick quick quick quick quick quick quick target target target target"
    "quick quick quick quick quick quick quick quick recommend recommend recommend recommend";
  gap:18px;
  align-items:stretch;
}
.home-card,.home-statistics{
  border:1px solid var(--home-border);
  border-radius:var(--home-radius-lg);
  background:var(--home-surface);
  box-shadow:var(--home-shadow-soft);
}
.home-card{padding:24px;}
.home-continue-card{grid-area:continue;min-height:390px;display:flex;flex-direction:column;overflow:hidden;position:relative;background:var(--home-primary);border-color:var(--home-primary);color:#fff;box-shadow:0 22px 50px rgba(36,59,115,.18);}
.home-continue-card::after{content:"学";position:absolute;right:-12px;bottom:-54px;color:rgba(255,255,255,.055);font-family:var(--jp);font-size:220px;font-weight:800;line-height:1;pointer-events:none;}
.home-continue-top,.home-card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;position:relative;z-index:1;}
.home-card-label-light{color:#DDE5FF;}
.home-session-status{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border:1px solid rgba(255,255,255,.18);border-radius:999px;background:rgba(255,255,255,.10);color:#fff;font-size:10px;font-weight:700;}
.home-session-status i{font-size:6px;color:#8DE0BE;}
.home-continue-content{position:relative;z-index:1;margin:auto 0 20px;}
.home-book-name{margin:0 0 8px;color:#BFCBF0;font-size:12px;font-weight:700;letter-spacing:.025em;text-transform:uppercase;}
.home-continue-card h2{margin:0;max-width:760px;color:#fff;font-size:clamp(29px,3vw,45px);line-height:1.12;letter-spacing:-.04em;text-wrap:balance;}
.home-title-divider{opacity:.45;}
.home-continue-description{max-width:680px;margin:12px 0 0;color:#D5DDF2;font-size:14px;line-height:1.65;}
.home-active-choice{width:fit-content;max-width:100%;margin-top:15px;padding:9px 11px;border:1px solid rgba(255,255,255,.13);border-radius:11px;background:rgba(255,255,255,.08);color:#EEF2FF;font-size:11px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.home-continue-progress{position:relative;z-index:1;margin-bottom:18px;}
.home-progress-copy{display:flex;justify-content:space-between;gap:16px;margin-bottom:8px;color:#DCE4FA;font-size:11px;}
.home-progress-copy strong{color:#fff;}
.home-progress-track{height:8px;border-radius:999px;background:rgba(255,255,255,.15);overflow:hidden;}
.home-progress-track span{display:block;width:0;height:100%;border-radius:inherit;background:#fff;transition:width .48s var(--home-ease);}
.home-continue-progress small{display:block;margin-top:7px;color:#BFCBE8;font-size:10px;}
.home-primary-actions{position:relative;z-index:1;display:flex;align-items:center;gap:10px;flex-wrap:wrap;}
.home-primary-actions .btn{min-height:48px;border-radius:14px;padding:0 17px;box-shadow:none;}
.home-primary-actions .home-main-button{background:#fff;color:var(--home-primary);border:1px solid #fff;}
.home-primary-actions .home-secondary-button{background:transparent;color:#fff;border:1px solid rgba(255,255,255,.28);}
.home-primary-actions .home-secondary-button:hover{background:rgba(255,255,255,.10);}

.home-vocab-card{grid-area:vocab;display:flex;flex-direction:column;min-height:390px;}
.home-card-head h2,.home-quick-actions h2,.home-target-copy h2,.home-recommendation h2{margin:7px 0 0;color:var(--home-text);font-size:20px;line-height:1.25;letter-spacing:-.025em;}
.home-icon-button{width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--home-border);border-radius:13px;background:var(--home-surface);color:var(--home-primary);}
.home-icon-button:hover,.home-icon-button.active{background:var(--home-primary-soft);border-color:#CFD8EE;}
.home-word-stage{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:22px 6px 18px;}
.home-word-index{margin-bottom:13px;color:var(--home-muted);font-family:var(--jp);font-size:10px;letter-spacing:.08em;text-transform:uppercase;}
.home-word-stage strong{max-width:100%;color:var(--home-text);font-size:clamp(38px,4.2vw,60px);line-height:1.18;overflow-wrap:anywhere;}
.home-word-stage>.jp:not(strong){margin-top:7px;color:#4C5A72;font-size:17px;font-weight:650;}
.home-word-stage>span:not(.jp):not(.home-word-index){margin-top:5px;color:var(--home-primary);font-size:12px;font-weight:750;}
.home-word-stage p{margin:12px 0 0;color:var(--home-text);font-size:16px;font-weight:700;}
.home-word-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;}
.home-word-button{min-height:46px;display:flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--home-border);border-radius:13px;background:var(--home-surface-secondary);color:#465268;font-size:12px;font-weight:700;}
.home-word-button:hover{border-color:#C9D3E6;background:var(--home-primary-soft);color:var(--home-primary);}

.home-statistics{grid-area:stats;display:grid;grid-template-columns:repeat(4,1fr);padding:7px;box-shadow:none;}
.home-stat-item{min-height:82px;display:flex;align-items:center;gap:13px;padding:13px 18px;border-right:1px solid var(--home-border);}
.home-stat-item:last-of-type{border-right:0;}
.home-stat-icon{width:42px;height:42px;display:grid;place-items:center;flex:0 0 auto;border-radius:13px;background:var(--home-surface-secondary);color:var(--home-primary);}
.home-stat-item>span:last-child{display:grid;gap:3px;min-width:0;}
.home-stat-item strong{color:var(--home-text);font-size:20px;line-height:1;font-variant-numeric:tabular-nums;}
.home-stat-item small{color:var(--home-muted);font-size:10px;line-height:1.3;}
.home-hidden-stat{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);}

.home-quick-actions{grid-area:quick;min-height:318px;}
.home-card-head-inline{align-items:center;}
.home-scroll-hint{color:var(--home-muted);font-size:10px;}
.home-quick-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:20px;}
.home-quick-item{min-height:80px;display:grid;grid-template-columns:46px minmax(0,1fr) 18px;align-items:center;gap:12px;padding:11px 13px;border:1px solid var(--home-border);border-radius:15px;background:var(--home-surface);color:var(--home-text);text-align:left;}
.home-quick-item:hover{border-color:#C8D2E4;background:var(--home-surface-secondary);transform:translateY(-1px);}
.home-quick-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:13px;background:var(--home-primary-soft);color:var(--home-primary);}
.home-quick-item>span:nth-child(2){display:grid;gap:3px;min-width:0;}
.home-quick-item strong{font-size:12px;}
.home-quick-item small{color:var(--home-muted);font-size:9.5px;line-height:1.35;}
.home-quick-item>i{color:#A5AEBC;font-size:10px;}

.home-daily-target{grid-area:target;display:grid;grid-template-columns:102px 1fr;align-items:center;gap:18px;min-height:150px;}
.home-target-ring{--target-progress:0deg;width:98px;height:98px;display:grid;place-items:center;border-radius:50%;background:conic-gradient(var(--home-primary) var(--target-progress),var(--home-primary-soft) 0);position:relative;}
.home-target-ring::before{content:"";position:absolute;inset:10px;border-radius:50%;background:var(--home-surface);}
.home-target-ring>span{position:relative;display:flex;align-items:baseline;gap:2px;color:var(--home-text);}
.home-target-ring strong{font-size:27px;line-height:1;}
.home-target-ring small{color:var(--home-muted);font-size:11px;font-weight:700;}
.home-target-copy p{margin:7px 0 0;color:var(--home-muted);font-size:11px;line-height:1.5;}
.home-text-button{margin-top:10px;padding:0;display:inline-flex;align-items:center;gap:8px;border:0;background:transparent;color:var(--home-primary);font-size:11px;font-weight:750;}

.home-recommendation{grid-area:recommend;display:grid;grid-template-columns:46px minmax(0,1fr);gap:13px;align-items:start;min-height:150px;background:var(--home-surface-secondary);box-shadow:none;}
.home-recommendation-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:14px;background:var(--home-primary);color:#fff;}
.home-recommendation h2{font-size:17px;}
.home-recommendation p{margin:7px 0 0;color:var(--home-muted);font-size:10.5px;line-height:1.5;}
.home-recommendation-button{grid-column:1/-1;min-height:43px;display:flex;align-items:center;justify-content:space-between;padding:0 13px;border:1px solid var(--home-border);border-radius:12px;background:var(--home-surface);color:var(--home-primary);font-size:11px;font-weight:750;}

@media (hover:hover){
  .home-profile-shortcut,.home-icon-button,.home-word-button,.home-quick-item,.home-text-button,.home-recommendation-button{transition:transform .2s var(--home-ease),border-color .2s ease,background .2s ease,color .2s ease,box-shadow .2s ease;}
}


