html[data-theme="dark"]{
  --home-background:#101522;
  --home-surface:#171D2C;
  --home-surface-secondary:#20283A;
  --home-text:#F6F7FB;
  --home-muted:#AAB3C5;
  --home-border:#2C3548;
  --home-primary-soft:#202E50;
  --home-shadow:none;
  --home-shadow-soft:none;
}
html[data-theme="dark"] body{background:var(--home-background);}
html[data-theme="dark"] .top-nav,html[data-theme="dark"] .bottom-nav{background:rgba(16,21,34,.97);border-color:var(--home-border);}
html[data-theme="dark"] .brand-icon{color:#9DB2F4;}
html[data-theme="dark"] .brand-copy strong,html[data-theme="dark"] .home-header h1,html[data-theme="dark"] .home-card h2,html[data-theme="dark"] .home-stat-item strong,html[data-theme="dark"] .home-word-stage strong,html[data-theme="dark"] .home-word-stage p{color:var(--home-text);}
html[data-theme="dark"] .home-card,html[data-theme="dark"] .home-statistics,html[data-theme="dark"] .home-streak,html[data-theme="dark"] .home-profile-shortcut,html[data-theme="dark"] .dropdown{background:var(--home-surface);border-color:var(--home-border);}
html[data-theme="dark"] .home-continue-card{background:var(--home-primary);border-color:var(--home-primary);}
html[data-theme="dark"] .home-word-button,html[data-theme="dark"] .home-quick-item,html[data-theme="dark"] .home-recommendation-button,html[data-theme="dark"] .home-icon-button{background:var(--home-surface-secondary);border-color:var(--home-border);color:var(--home-text);}
html[data-theme="dark"] .home-target-ring::before{background:var(--home-surface);}
html[data-theme="dark"] .home-recommendation{background:var(--home-surface-secondary);}

:where(.home-page,.top-nav,.bottom-nav) button:focus-visible,
:where(.home-page,.top-nav,.bottom-nav) [tabindex]:focus-visible{
  outline:3px solid rgba(36,59,115,.28);
  outline-offset:3px;
}
@media (prefers-reduced-motion:reduce){
  .home-page *, .home-page *::before, .home-page *::after{animation-duration:.01ms;animation-iteration-count:1;transition-duration:.01ms;scroll-behavior:auto;}
}

