/* source-style: wikaru-loading-motion-final */
#loadingScreen.loader{
  position:fixed!important;
  inset:0!important;
  z-index:3000!important;
  display:grid!important;
  place-items:center!important;
  overflow:hidden!important;
  padding:max(18px,env(safe-area-inset-top)) max(16px,env(safe-area-inset-right)) max(18px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left))!important;
  opacity:1;
  visibility:visible;
  background:
    radial-gradient(circle at 18% 15%,rgba(125,181,255,.22),transparent 31%),
    radial-gradient(circle at 86% 82%,rgba(232,75,60,.14),transparent 30%),
    linear-gradient(145deg,#f9fbff 0%,#f4f5f0 48%,#fff8fb 100%)!important;
  transition:opacity .46s ease,visibility .46s ease!important;
  isolation:isolate;
}
#loadingScreen.loader[hidden]{display:none!important;}
#loadingScreen.loader.is-leaving{
  opacity:0!important;
  visibility:hidden!important;
}
#loadingScreen .loader-ambient{
  position:absolute;
  z-index:-1;
  width:min(48vw,560px);
  aspect-ratio:1;
  border-radius:50%;
  filter:blur(8px);
  opacity:.54;
  pointer-events:none;
  animation:wkLoaderDrift 7s ease-in-out infinite alternate;
}
#loadingScreen .loader-ambient-one{
  top:-22%;left:-10%;
  background:radial-gradient(circle,rgba(36,59,115,.18),transparent 67%);
}
#loadingScreen .loader-ambient-two{
  right:-12%;bottom:-26%;
  background:radial-gradient(circle,rgba(35,199,154,.14),transparent 67%);
  animation-delay:-2.6s;
}
#loadingScreen .loader-card{
  position:relative;
  width:min(410px,100%)!important;
  padding:36px 34px 28px!important;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.92)!important;
  border-radius:30px!important;
  background:rgba(255,255,255,.88)!important;
  box-shadow:0 30px 90px rgba(23,32,51,.16)!important;
  backdrop-filter:blur(24px) saturate(1.08)!important;
  -webkit-backdrop-filter:blur(24px) saturate(1.08)!important;
  animation:wkLoaderCardIn .58s cubic-bezier(.2,.8,.2,1) both,wkLoaderCardFloat 3.8s ease-in-out .7s infinite;
}
#loadingScreen .loader-card::after{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(120deg,transparent 24%,rgba(255,255,255,.52) 44%,transparent 65%);
  transform:translateX(-130%);
  animation:wkLoaderSheen 3.3s ease-in-out 1s infinite;
}
#loadingScreen .loader-visual{
  position:relative;
  width:112px;
  height:112px;
  margin:0 auto 8px;
  display:grid;
  place-items:center;
}
#loadingScreen .loader-logo{
  position:relative;
  z-index:3;
  width:76px!important;
  height:76px!important;
  margin:0!important;
  color:#243B73!important;
  filter:drop-shadow(0 12px 22px rgba(36,59,115,.22));
  animation:wkLoaderLogoPulse 1.8s ease-in-out infinite!important;
}
#loadingScreen .loader-orbit{
  position:absolute;
  inset:3px;
  z-index:1;
  border:1px solid rgba(36,59,115,.13);
  border-radius:50%;
  animation:wkLoaderOrbit 4.8s linear infinite;
}
#loadingScreen .loader-orbit::before{
  content:"";
  position:absolute;
  inset:12px;
  border:1px dashed rgba(36,59,115,.17);
  border-radius:50%;
  animation:wkLoaderOrbitReverse 3.6s linear infinite;
}
#loadingScreen .loader-orbit span{
  position:absolute;
  width:8px;
  height:8px;
  border-radius:50%;
  background:#243B73;
  box-shadow:0 5px 14px rgba(36,59,115,.24);
}
#loadingScreen .loader-orbit span:nth-child(1){top:-4px;left:50%;transform:translateX(-50%);}
#loadingScreen .loader-orbit span:nth-child(2){right:6px;bottom:15px;background:#E84B3C;}
#loadingScreen .loader-orbit span:nth-child(3){left:3px;bottom:25px;background:#23c79a;}
#loadingScreen .loader-kana{
  position:absolute;
  z-index:4;
  display:grid;
  place-items:center;
  width:28px;
  height:28px;
  border:1px solid rgba(36,59,115,.12);
  border-radius:10px;
  color:#243B73;
  background:rgba(255,255,255,.94);
  box-shadow:0 9px 20px rgba(23,32,51,.10);
  font-family:"Noto Sans JP",sans-serif;
  font-size:13px;
  font-weight:800;
  animation:wkLoaderKana 2.6s ease-in-out infinite;
}
#loadingScreen .loader-kana-one{left:-8px;top:14px;}
#loadingScreen .loader-kana-two{right:-7px;top:24px;animation-delay:-.9s;}
#loadingScreen .loader-kana-three{right:8px;bottom:-1px;animation-delay:-1.7s;}
#loadingScreen .loader-wordmark{
  position:relative;
  z-index:2;
  font-size:28px!important;
  font-weight:850!important;
  letter-spacing:-.055em!important;
}
#loadingScreen .loader-card h3{
  position:relative;
  z-index:2;
  margin:16px 0 6px!important;
  font-size:18px!important;
  letter-spacing:-.025em;
}
#loadingScreen .loader-card p{
  position:relative;
  z-index:2;
  margin:0 auto!important;
  max-width:310px;
  line-height:1.55;
}
#loadingScreen .loader-status-line{
  position:relative;
  z-index:2;
  min-height:32px;
  margin:16px 0 0;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:9px;
  color:#536078;
  font-size:12px;
  font-weight:750;
}
#loadingScreen .loader-dots{display:inline-flex;align-items:center;gap:4px;}
#loadingScreen .loader-dots i{
  width:5px;height:5px;border-radius:50%;background:#243B73;
  animation:wkLoaderDot .9s ease-in-out infinite alternate;
}
#loadingScreen .loader-dots i:nth-child(2){animation-delay:.16s;}
#loadingScreen .loader-dots i:nth-child(3){animation-delay:.32s;}
#loadingScreen .loader-bar{
  position:relative;
  z-index:2;
  height:7px!important;
  margin:11px 0 0!important;
  overflow:hidden!important;
  border-radius:999px!important;
  background:#e8edf7!important;
}
#loadingScreen .loader-fill{
  width:38%!important;
  height:100%!important;
  border-radius:inherit!important;
  background:linear-gradient(90deg,#243B73,#7db5ff,#23c79a)!important;
  animation:wkLoaderProgress 1.45s cubic-bezier(.4,0,.2,1) infinite!important;
  box-shadow:0 0 18px rgba(125,181,255,.34);
}
#loadingScreen .loader-skip{
  position:relative;
  z-index:3;
  width:100%;
  min-height:44px;
  margin-top:15px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:9px;
  border:1px solid rgba(36,59,115,.16);
  border-radius:14px;
  color:#243B73;
  background:rgba(233,237,250,.76);
  font:inherit;
  font-size:12px;
  font-weight:800;
  opacity:0;
  visibility:hidden;
  transform:translateY(7px);
  transition:opacity .22s ease,visibility .22s ease,transform .22s ease,background .18s ease;
}
#loadingScreen.loader.is-slow .loader-skip{
  opacity:1;
  visibility:visible;
  transform:none;
}
#loadingScreen .loader-skip:hover{background:#E9EDFA;}
#loadingScreen .loader-skip:focus-visible{outline:3px solid rgba(36,59,115,.28);outline-offset:3px;}
#loadingScreen .loader-card small{
  position:relative;
  z-index:2;
  margin-top:14px!important;
}
html[data-theme="dark"] #loadingScreen.loader{
  background:
    radial-gradient(circle at 18% 15%,rgba(78,104,171,.25),transparent 31%),
    radial-gradient(circle at 86% 82%,rgba(35,199,154,.12),transparent 30%),
    linear-gradient(145deg,#101411 0%,#141a24 52%,#17141a 100%)!important;
}
html[data-theme="dark"] #loadingScreen .loader-card{
  border-color:rgba(255,255,255,.10)!important;
  background:rgba(21,27,39,.89)!important;
  box-shadow:0 34px 100px rgba(0,0,0,.44)!important;
}
html[data-theme="dark"] #loadingScreen .loader-status-line{color:#b9c2d3;}
html[data-theme="dark"] #loadingScreen .loader-kana{color:#dce5ff;background:#253149;border-color:#35425f;}
html[data-theme="dark"] #loadingScreen .loader-bar{background:#283247!important;}
