@keyframes wkLoaderCardIn{from{opacity:0;transform:translateY(18px) scale(.97)}to{opacity:1;transform:none}}
@keyframes wkLoaderCardFloat{0%,100%{translate:0 0}50%{translate:0 -5px}}
@keyframes wkLoaderDrift{from{transform:translate3d(-2%,0,0) scale(.96)}to{transform:translate3d(5%,4%,0) scale(1.08)}}
@keyframes wkLoaderSheen{0%,58%{transform:translateX(-130%)}82%,100%{transform:translateX(130%)}}
@keyframes wkLoaderLogoPulse{0%,100%{transform:scale(1) rotate(0)}50%{transform:scale(1.045) rotate(1.5deg)}}
@keyframes wkLoaderOrbit{to{transform:rotate(360deg)}}
@keyframes wkLoaderOrbitReverse{to{transform:rotate(-360deg)}}
@keyframes wkLoaderKana{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-7px) rotate(3deg)}}
@keyframes wkLoaderDot{from{opacity:.3;transform:translateY(0)}to{opacity:1;transform:translateY(-3px)}}
@keyframes wkLoaderProgress{0%{transform:translateX(-120%)}65%{transform:translateX(175%)}100%{transform:translateX(270%)}}
