#quizPage .quiz-card-wrap{position:relative;isolation:isolate;}
.wk-play-feedback{position:absolute;z-index:35;top:17px;left:50%;width:max-content;max-width:calc(100% - 32px);transform:translateX(-50%);pointer-events:none;display:grid;grid-template-columns:42px minmax(0,1fr);align-items:center;gap:10px;padding:8px 14px 8px 9px;border:1px solid rgba(255,255,255,.82);border-radius:18px;color:#fff;box-shadow:0 18px 42px rgba(23,32,51,.20);overflow:visible;}
.wk-play-feedback.correct{background:linear-gradient(135deg,#243B73 0%,#2F7180 54%,#23C79A 100%);}
.wk-play-feedback.wrong{background:linear-gradient(135deg,#243B73 0%,#72536F 54%,#F06A78 100%);}
.wk-play-stamp{width:42px;height:42px;display:grid;place-items:center;border-radius:15px;background:rgba(255,255,255,.18);font-family:var(--jp);font-size:24px;font-weight:900;box-shadow:inset 0 0 0 1px rgba(255,255,255,.16);}
