.wk-play-copy small{font-size:10.5px;line-height:1.25;color:rgba(255,255,255,.82);font-weight:700;white-space:normal;}
.wk-play-particle{position:absolute;width:8px;height:12px;border-radius:3px;opacity:0;pointer-events:none;}
.wk-play-feedback.correct .wk-play-particle{background:var(--particle,#FFD36D);animation:wk20Confetti .52s var(--wk20-ease-soft) both;}
.wk-play-feedback.wrong .wk-play-particle{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,.82);animation:wk20SoftDots .42s var(--wk20-ease-soft) both;}
.wk-play-particle:nth-child(3){--x:-52px;--y:-30px;--r:-28deg;--particle:#FFD36D;left:25%;top:32%;}
.wk-play-particle:nth-child(4){--x:48px;--y:-34px;--r:32deg;--particle:#7DB5FF;right:25%;top:30%;animation-delay:.03s!important;}
.wk-play-particle:nth-child(5){--x:-34px;--y:35px;--r:44deg;--particle:#F7B6C2;left:37%;bottom:15%;animation-delay:.06s!important;}
.wk-play-particle:nth-child(6){--x:38px;--y:31px;--r:-42deg;--particle:#B9E8D7;right:36%;bottom:14%;animation-delay:.08s!important;}
#quizPage.wk-play-correct .quiz-card-wrap{animation:wk20CorrectCard .46s var(--wk20-ease-spring) both;}
#quizPage.wk-play-wrong .quiz-card-wrap{animation:wk20WrongCard .38s var(--wk20-ease-soft) both;}
#quizPage.wk-play-correct .flash-face{box-shadow:inset 0 0 0 3px rgba(35,199,154,.16)!important;}
#quizPage.wk-play-wrong .flash-face{box-shadow:inset 0 0 0 3px rgba(240,106,120,.14)!important;}
@keyframes wk20CorrectCard{0%{transform:translateY(0) scale(1)}34%{transform:translateY(-6px) rotate(-.25deg) scale(1.008)}65%{transform:translateY(1px) rotate(.12deg) scale(.998)}100%{transform:none}}
@keyframes wk20WrongCard{0%{transform:translateX(0) scale(1)}24%{transform:translateX(-3px) rotate(-.18deg) scale(.996)}50%{transform:translateX(3px) rotate(.18deg)}74%{transform:translateX(-1px)}100%{transform:none}}
@keyframes wk20FeedbackIn{0%{opacity:0;transform:translate(-50%,-10px) scale(.88)}62%{opacity:1;transform:translate(-50%,2px) scale(1.025)}100%{opacity:1;transform:translate(-50%,0) scale(1)}}
@keyframes wk20FeedbackOut{to{opacity:0;transform:translate(-50%,-6px) scale(.96)}}
@keyframes wk20Confetti{0%{opacity:0;transform:translate(0,0) rotate(0) scale(.7)}25%{opacity:1}100%{opacity:0;transform:translate(var(--x),var(--y)) rotate(var(--r)) scale(1)}}
@keyframes wk20SoftDots{0%{opacity:0;transform:translate(0,0) scale(.4)}45%{opacity:.9}100%{opacity:0;transform:translate(calc(var(--x)*.45),calc(var(--y)*.42)) scale(1)}}
