@media(prefers-reduced-motion:reduce){#quizPage.wk-play-correct .quiz-card-wrap,#quizPage.wk-play-wrong .quiz-card-wrap,.wk-play-feedback,.wk-play-particle{animation:none!important}.wk-play-particle{display:none!important}}

