.material-voice-card{
  margin:20px 0 24px;padding:20px;border:1px solid rgba(36,59,115,.14);border-radius:24px;
  background:linear-gradient(135deg,rgba(255,255,255,.96),rgba(242,246,255,.9));box-shadow:0 12px 28px rgba(36,59,115,.07);
}
.material-voice-head{display:flex;align-items:center;gap:14px;margin-bottom:15px;}
.material-voice-icon{width:48px;height:48px;display:grid;place-items:center;flex:0 0 auto;border-radius:17px;color:#fff;background:linear-gradient(135deg,#243B73,#5f83d2);box-shadow:0 12px 24px rgba(36,59,115,.2);}
.material-voice-kicker{display:block;color:#243B73;font-size:11px;font-weight:850;text-transform:uppercase;letter-spacing:.055em;}
.material-voice-head h3{margin:3px 0 2px;font-size:19px;}
.material-voice-head p{margin:0;font-size:12px;line-height:1.45;}
.material-voice-switcher,.wk8-voice-switcher{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;}
.material-voice-card .wk8-voice-choice,
#quizPage .wk8-voice-choice{
  min-width:0;min-height:74px;padding:10px 7px;border:1px solid rgba(36,59,115,.14);border-radius:17px;
  background:#fff;color:#27334d;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;
  font-weight:800;box-shadow:0 8px 18px rgba(36,59,115,.055);transition:.18s ease;
}
.material-voice-card .wk8-voice-choice i,#quizPage .wk8-voice-choice i{font-size:17px;color:#243B73;}
.material-voice-card .wk8-voice-choice span,#quizPage .wk8-voice-choice span{font-size:12px;text-align:center;}
.material-voice-card .wk8-voice-choice small,#quizPage .wk8-voice-choice small{font-size:10px;font-weight:650;color:#6b7890;line-height:1.2;text-align:center;}
.material-voice-card .wk8-voice-choice:hover,#quizPage .wk8-voice-choice:hover{transform:translateY(-2px);border-color:rgba(36,59,115,.34);box-shadow:0 13px 25px rgba(36,59,115,.11);}
.material-voice-card .wk8-voice-choice.active,#quizPage .wk8-voice-choice.active{
  color:#fff;border-color:transparent;background:linear-gradient(135deg,#243B73,#5073bd);box-shadow:0 13px 27px rgba(36,59,115,.22);
}
.material-voice-card .wk8-voice-choice.active i,#quizPage .wk8-voice-choice.active i{color:#fff;}
.material-voice-card .wk8-voice-choice.active small,#quizPage .wk8-voice-choice.active small{color:rgba(255,255,255,.82);}
html[data-theme="dark"] .material-voice-card{background:linear-gradient(135deg,#202633,#1b2330);border-color:#394156;}
html[data-theme="dark"] .material-voice-head h3{color:#f2f5fb;}
html[data-theme="dark"] .material-voice-head p{color:#aeb8c8;}
html[data-theme="dark"] .material-voice-card .wk8-voice-choice{background:#222735;border-color:#394156;color:#e9edf7;}
@media(max-width:900px){.material-voice-switcher,.wk8-voice-switcher{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:450px){
  .material-voice-card{padding:16px;margin:16px 0 20px;}
  .material-voice-head{align-items:flex-start;}
  .material-voice-card .wk8-voice-choice,#quizPage .wk8-voice-choice{min-height:68px;padding:8px 5px;}
  .material-voice-card .wk8-voice-choice small,#quizPage .wk8-voice-choice small{display:none;}
}

