/* source-style: wikaru-number-appendix-style */
body.number-appendix-active #materialPage{width:min(1580px,calc(100% - 44px))}
body.number-appendix-active #materialPage .content-card{padding:30px}
.number-appendix-root{display:grid;gap:22px}
.number-hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1.45fr) minmax(280px,.75fr);gap:24px;padding:30px;border-radius:30px;background:linear-gradient(135deg,#f6f0ff 0%,#eef8ff 48%,#fff8ed 100%);border:1px solid rgba(36,59,115,.14);box-shadow:0 18px 44px rgba(36,59,115,.10)}
