.number-hero-copy{position:relative;z-index:1}
.number-kicker{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border-radius:999px;background:#fff;color:#243B73;font-size:12px;font-weight:850;box-shadow:0 8px 20px rgba(36,59,115,.09)}
.number-hero h3{margin:15px 0 5px;font-size:clamp(34px,4vw,58px);letter-spacing:-.055em}
.number-hero .jp-sub{font-family:var(--jp);font-size:clamp(19px,2vw,28px);font-weight:760;color:#243B73}
.number-hero p{max-width:780px;margin:12px 0 0;color:#4d5870;font-weight:600}
.number-hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
.number-summary{position:relative;z-index:1;display:grid;grid-template-columns:1fr 1fr;gap:10px;align-content:center}
