.number-summary-item span{display:block;margin-top:4px;color:#66728a;font-size:11px;font-weight:750}
.number-learning-title{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}
.number-learning-title h3{font-size:clamp(24px,2.8vw,36px);margin:0}
.number-learning-title p{margin:5px 0 0}
.number-rule-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
