.number-rule-card p{margin:0;font-size:13px;line-height:1.65}
.number-formula{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:12px;padding:11px;border-radius:15px;background:#F7F7F2;border:1px solid #E7E9E2;font-family:var(--jp);font-weight:800;color:#243B73}
.number-formula b{display:inline-grid;place-items:center;min-height:31px;padding:4px 9px;border-radius:10px;background:#fff;border:1px solid #dde4f5}
.number-warning-panel{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:16px;padding:21px;border-radius:25px;background:linear-gradient(135deg,#fff8dd,#fff,#eef8ff);border:1px solid rgba(197,142,0,.18)}
