.number-warning-panel p{margin:0;font-size:13px}
.number-exception-list{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}
.number-exception{padding:11px 8px;border-radius:15px;background:#fff;border:1px solid #ece4c9;text-align:center}
.number-exception strong{display:block;color:#071b45;font-size:15px}
.number-exception span{display:block;margin-top:4px;font-family:var(--jp);font-size:14px;font-weight:800;color:#9b6800}
.number-lab{padding:22px;border-radius:27px;background:linear-gradient(145deg,#fff,#f8fbff);border:1px solid #DDE5F2;box-shadow:0 14px 32px rgba(36,59,115,.07)}
