/* source-style: wikaru-number-card-cleanup-v7 */
body.number-appendix-active .number-card-grid{
  grid-template-columns:repeat(auto-fill,minmax(260px,1fr))!important;
  gap:15px!important;
}
body.number-appendix-active .number-card{
  display:grid!important;
  grid-template-columns:minmax(96px,124px) minmax(0,1fr) 44px!important;
  grid-template-rows:1fr!important;
  align-items:center!important;
  gap:14px!important;
  min-height:126px!important;
  padding:17px 16px!important;
  border-radius:22px!important;
  overflow:hidden!important;
}


body.number-appendix-active .number-card > :not(.number-card-value):not(.number-card-reading):not(.number-audio-btn){
  display:none!important;
}


body.number-appendix-active .number-card :is(
  .card-actions,.number-card-actions,.vocab-actions,.material-card-actions,
  [class*="bottom-actions"],[class*="footer-actions"],[class*="card-footer"]
){
  display:none!important;
}
body.number-appendix-active .number-card button:not(.number-audio-btn){
  display:none!important;
}

body.number-appendix-active .number-card-value{
  width:100%!important;
  max-width:124px!important;
  min-height:72px!important;
  padding:10px 8px!important;
  border-radius:18px!important;
  font-size:clamp(17px,1.35vw,22px)!important;
  line-height:1.1!important;
  align-self:center!important;
}
body.number-appendix-active .number-card-value.is-long{
  font-size:15px!important;
}
body.number-appendix-active .number-card-value.is-very-long{
  font-size:12px!important;
}
body.number-appendix-active .number-card-reading{
  display:flex!important;
  flex-direction:column!important;
  justify-content:center!important;
  align-self:stretch!important;
  min-width:0!important;
  padding:2px 0!important;
}
body.number-appendix-active .number-card-reading strong{
  font-size:clamp(18px,1.4vw,23px)!important;
  line-height:1.35!important;
  letter-spacing:-.02em!important;
}
body.number-appendix-active .number-card-reading small{
  margin-top:5px!important;
  font-size:12px!important;
  line-height:1.35!important;
