  margin-inline:auto!important;
  gap:0!important;
}
body.marker-quiz-active #quizPage .quiz-card-wrap{
  width:100%;
  min-width:0;
  padding:0!important;
  border:0!important;
  background:transparent!important;
  box-shadow:none!important;
}
body.marker-quiz-active #markerQuizPanel{width:100%;min-width:0}
.marker-quiz-shell{
  width:100%;
  max-width:1320px;
  margin-inline:auto;
  gap:18px;
  padding:22px;
  border-radius:32px;
  background:
    radial-gradient(circle at 9% 2%,rgba(125,181,255,.14),transparent 29%),
    radial-gradient(circle at 94% 98%,rgba(86,201,169,.12),transparent 30%),
    linear-gradient(145deg,rgba(255,255,255,.94),rgba(247,249,255,.89));
  border:1px solid rgba(36,59,115,.13);
  box-shadow:0 28px 80px rgba(36,59,115,.12);
}
.marker-quiz-top{
  min-height:82px;
