  border-radius:18px;
}
.marker-quiz-brand strong{font-size:18px}
.marker-quiz-brand small{font-size:11px}
.marker-quiz-stats{gap:9px}
.marker-quiz-stat{
  min-width:88px;
  padding:10px 13px;
  border:1px solid rgba(36,59,115,.08);
}
.marker-quiz-progress{
  height:9px;
  margin-inline:4px;
  background:rgba(36,59,115,.085);
}
.marker-quiz-progress span{
  position:relative;
  overflow:hidden;
}
.marker-quiz-progress span::after{
  content:"";
  position:absolute;
  inset:0;
  transform:translateX(-120%);
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.72),transparent);
  animation:markerProgressSweep 1.8s ease-in-out infinite;
}
.marker-question-card{
  display:grid;
  grid-template-columns:minmax(0,1.18fr) minmax(350px,.82fr);
  grid-template-areas:
    "head head"
    "cue cue"
    "card speech"
    "card answer"
    "card feedback";
  column-gap:22px;
  row-gap:14px;
  min-height:590px;
  padding:clamp(22px,2.8vw,36px);
  border-radius:29px;
  background:
    radial-gradient(circle at 4% 0%,rgba(125,181,255,.13),transparent 31%),
    linear-gradient(145deg,#fff 0%,#fbfcff 57%,#f4f8ff 100%);
}
.marker-question-head{grid-area:head}
.marker-question-cue{
  grid-area:cue;
  margin:0;
  text-align:left;
  padding:0 2px;
  font-size:13.5px;
}
.marker-flash-stage{
  grid-area:card;
  width:100%;
  max-width:none;
  min-height:470px;
  height:100%;
  margin:0;
}
.marker-flash-face{
  padding:clamp(24px,3.5vw,46px);
  border-radius:27px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 18px 42px rgba(36,59,115,.08);
}
.marker-question-value{font-size:clamp(56px,6.4vw,94px)}
.marker-question-value.reading{font-size:clamp(40px,5vw,70px)}
.marker-question-hint{font-size:13px;line-height:1.5}
.marker-speech-panel{
  grid-area:speech;
  width:100%;
  max-width:none;
  margin:0;
  padding:16px;
  border-radius:22px;
  align-self:start;
  background:linear-gradient(145deg,#fbfcff,#f4f7fc);
  box-shadow:0 12px 28px rgba(36,59,115,.055);
}
.marker-answer-zone{
  grid-area:answer;
  width:100%;
  max-width:none;
  margin:0;
  padding:17px;
  border-radius:22px;
  align-self:start;
}
.marker-feedback{
  grid-area:feedback;
  width:100%;
  max-width:none;
  margin:0;
  align-self:start;
}
.marker-answer-input{min-height:64px}
.marker-submit{min-width:128px;min-height:64px}
.marker-quiz-bottom{
  min-height:48px;
  padding:0 8px;
}


.marker-audio{
  position:relative;
  isolation:isolate;
  overflow:visible;
  transition:transform .22s cubic-bezier(.2,.8,.2,1),background .22s ease,color .22s ease,border-color .22s ease,box-shadow .22s ease;
}
.marker-audio::before,.marker-audio::after{
  content:"";
  position:absolute;
  inset:-1px;
  z-index:-1;
  border-radius:14px;
  border:2px solid rgba(36,59,115,.27);
  opacity:0;
  pointer-events:none;
}
.marker-audio:hover{
  transform:translateY(-2px);
  color:#fff;
  border-color:transparent;
  background:linear-gradient(135deg,#243B73,#35549D);
  box-shadow:0 12px 24px rgba(36,59,115,.18);
}
.marker-audio.is-playing{
  color:#fff;
  border-color:transparent;
  background:linear-gradient(135deg,#243B73,#20b88c);
  box-shadow:0 13px 28px rgba(36,59,115,.24);
  transform:translateY(-2px) scale(1.04);
}
.marker-audio.is-playing::before{animation:markerAudioRipple 1.25s cubic-bezier(.2,.7,.2,1) infinite}
.marker-audio.is-playing::after{animation:markerAudioRipple 1.25s .38s cubic-bezier(.2,.7,.2,1) infinite}
.marker-audio.is-playing i{animation:markerSpeakerBreathe .72s ease-in-out infinite alternate}
.marker-row.is-audio-active{
  background:linear-gradient(90deg,rgba(36,59,115,.06),rgba(86,201,169,.08));
  box-shadow:inset 3px 0 0 #35549D;
}


.marker-speech-icon{
  overflow:visible;
  isolation:isolate;
  transition:transform .25s ease,background .25s ease,color .25s ease,box-shadow .25s ease;
}
.marker-speech-icon::before,.marker-speech-icon::after{
  content:"";
  position:absolute;
  inset:-4px;
  z-index:-1;
  border-radius:20px;
  border:1.5px solid rgba(36,59,115,.22);
  opacity:0;
}
.marker-speech-panel.listening{
  background:linear-gradient(135deg,#eef3ff,#ecfbf7);
  box-shadow:0 0 0 4px rgba(36,59,115,.055),0 14px 30px rgba(36,59,115,.09);
}
.marker-speech-panel.listening .marker-speech-icon{
  transform:translateY(-1px);
  box-shadow:0 11px 25px rgba(36,59,115,.24);
}
.marker-speech-panel.listening .marker-speech-icon::before{animation:markerMicHalo 1.55s ease-out infinite}
.marker-speech-panel.listening .marker-speech-icon::after{animation:markerMicHalo 1.55s .48s ease-out infinite}
.marker-speech-panel.listening .marker-speech-icon i{animation:markerMicFloat .8s ease-in-out infinite alternate}
.marker-speech-icon b{
  width:3px;
  bottom:5px;
  transform-origin:center bottom;
  animation-timing-function:ease-in-out!important;
}
.marker-speech-panel.listening .marker-speech-icon b:nth-of-type(1){animation-duration:.72s!important}
.marker-speech-panel.listening .marker-speech-icon b:nth-of-type(2){animation-duration:.88s!important}
.marker-speech-panel.listening .marker-speech-icon b:nth-of-type(3){animation-duration:.68s!important}
.marker-speech-restart{
  transition:transform .2s ease,background .2s ease,color .2s ease,border-color .2s ease,box-shadow .2s ease;
}
.marker-speech-restart:hover{
  transform:translateY(-1px);
  color:#fff;
  background:#243B73;
  border-color:#243B73;
  box-shadow:0 10px 22px rgba(36,59,115,.16);
}

@keyframes markerAudioRipple{
  0%{transform:scale(.84);opacity:.52}
  72%,100%{transform:scale(1.75);opacity:0}
}
@keyframes markerSpeakerBreathe{
  from{transform:scale(.92)}
  to{transform:scale(1.13)}
}
@keyframes markerMicHalo{
  0%{transform:scale(.82);opacity:.48}
  76%,100%{transform:scale(1.55);opacity:0}
}
@keyframes markerMicFloat{
  from{transform:translateY(1px) scale(.96)}
  to{transform:translateY(-1px) scale(1.06)}
}
@keyframes markerProgressSweep{
  0%{transform:translateX(-120%)}
  58%,100%{transform:translateX(150%)}
}

