/* source-style: wikaru-revisi-9-motion-icon-style */
:root{
  --wk-motion-fast:220ms;
  --wk-motion-medium:420ms;
  --wk-motion-long:760ms;
  --wk-motion-ease:cubic-bezier(.2,.82,.22,1);
  --wk-motion-spring:cubic-bezier(.18,1.18,.32,1);
}
html[data-wk-motion="full"]{scroll-behavior:smooth}


.wk-motion-constellation{
  position:absolute;
  inset:14px 72px auto auto;
  width:118px;
  height:82px;
  pointer-events:none;
  opacity:.96;
  filter:drop-shadow(0 12px 24px rgba(36,59,115,.12));
}
.wk-motion-orbit{
  position:absolute;
  left:50%;top:50%;
  width:72px;height:72px;
  transform:translate(-50%,-50%);
  border:1px dashed color-mix(in srgb,var(--wk-primary,#315FAE) 28%,transparent);
  border-radius:50%;
}
.wk-motion-core{
  position:absolute;left:50%;top:50%;width:42px;height:42px;
  transform:translate(-50%,-50%);
  display:grid;place-items:center;border-radius:15px;
  color:#fff;background:linear-gradient(145deg,#315FAE,#0F766E);
  box-shadow:0 12px 28px rgba(36,59,115,.20);
  font-family:var(--jp);font-size:22px;font-weight:850;
}
.wk-motion-token{
  position:absolute;left:50%;top:50%;width:28px;height:28px;margin:-14px;
  display:grid;place-items:center;border-radius:10px;
  color:var(--wk-primary,#315FAE);background:var(--wk-surface,#fff);
  border:1px solid var(--wk-line,#d9e2ee);font-size:12px;font-weight:850;
  box-shadow:0 8px 18px rgba(28,48,82,.10);
  transform:rotate(var(--wk-angle)) translateX(41px) rotate(var(--wk-angle-neg));
}
html[data-wk-motion="full"] .wk-motion-orbit{animation:wkOrbitSpin 8s linear infinite}
html[data-wk-motion="full"] .wk-motion-core{animation:wkCoreBreathe 2.8s ease-in-out infinite}
html[data-wk-motion="full"] .wk-motion-token{animation:wkTokenFloat 2.4s ease-in-out infinite alternate}
html[data-wk-motion="full"] .wk-motion-token:nth-child(3){animation-delay:-.8s}
html[data-wk-motion="full"] .wk-motion-token:nth-child(4){animation-delay:-1.5s}
@keyframes wkOrbitSpin{to{transform:translate(-50%,-50%) rotate(360deg)}}
@keyframes wkCoreBreathe{50%{transform:translate(-50%,-50%) scale(1.075);box-shadow:0 17px 34px rgba(36,59,115,.25)}}
@keyframes wkTokenFloat{to{translate:0 -5px}}

#setupModal .modal-fixed-head{position:relative;padding-right:170px!important}
#setupModal .step-block.active.wk-step-motion-in{animation:wkStepEnter .42s var(--wk-motion-ease) both!important}
@keyframes wkStepEnter{from{opacity:0;transform:translateX(26px) scale(.985)}to{opacity:1;transform:none}}


.wk-inline-icon{width:23px;height:23px;display:block;overflow:visible;color:inherit}
.wk-inline-icon *{vector-effect:non-scaling-stroke}
.option-soft-icon .wk-inline-icon{width:23px;height:23px}
.wk-category-icon .wk-inline-icon{width:21px;height:21px}
#setupModal .soft-step-icon .wk-inline-icon{width:20px;height:20px}

#setupModal :is(.option-card,.category-button){
  isolation:isolate;
  will-change:transform,box-shadow;
  transform-origin:center;
}
#setupModal :is(.option-card,.category-button)::before{
  content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;
  background:radial-gradient(circle at var(--wk-ripple-x,50%) var(--wk-ripple-y,50%),rgba(255,255,255,.58),transparent 42%);
  opacity:0;transform:scale(.75);z-index:0;
}
#setupModal :is(.option-card,.category-button).wk-card-ripple::before{
  animation:wkCardRipple .48s ease-out both!important;
}
@keyframes wkCardRipple{0%{opacity:.62;transform:scale(.65)}100%{opacity:0;transform:scale(1.35)}}
html[data-wk-motion="full"] #setupModal :is(.option-card,.category-button):hover{
  transform:translateY(-4px) scale(1.012)!important;
}
html[data-wk-motion="full"] #setupModal :is(.option-card,.category-button):hover :is(.option-soft-icon,.wk-category-icon){
  transform:translateY(-1px) rotate(-4deg) scale(1.06);
}
#setupModal :is(.option-soft-icon,.wk-category-icon){
  transition:transform .26s var(--wk-motion-spring),background .22s ease,color .22s ease!important;
}
#setupModal :is(.option-card,.category-button).wk-card-selected{
  animation:wkCardSelected .46s var(--wk-motion-spring) both!important;
}
#setupModal :is(.option-card,.category-button).wk-card-selected :is(.option-soft-icon,.wk-category-icon){
  animation:wkIconSelected .52s var(--wk-motion-spring) both!important;
}
@keyframes wkCardSelected{0%{transform:scale(.975)}55%{transform:scale(1.025)}100%{transform:scale(1)}}
@keyframes wkIconSelected{0%{transform:scale(.72) rotate(-14deg)}58%{transform:scale(1.16) rotate(7deg)}100%{transform:scale(1) rotate(0)}}

.setup-progress-line{position:relative;overflow:hidden!important}
html[data-wk-motion="full"] .setup-progress-line::after{
  content:"";position:absolute;inset:0 auto 0 -35%;width:32%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.72),transparent);
  transform:skewX(-18deg);animation:wkProgressGleam 2.4s ease-in-out infinite;
}
@keyframes wkProgressGleam{0%,30%{left:-38%}75%,100%{left:112%}}


.wk-theme-motion-overlay-v8,.theme-transition-overlay{display:none!important}
.wk-theme-v9-overlay{
  position:fixed;inset:0;z-index:12000;overflow:hidden;pointer-events:none;isolation:isolate;
}
.wk-theme-v9-wash{
  position:absolute;left:var(--wk-theme-x);top:var(--wk-theme-y);
  width:var(--wk-theme-size);height:var(--wk-theme-size);border-radius:50%;
  transform:translate(-50%,-50%) scale(.002);will-change:transform;
}
.wk-theme-v9-overlay.to-dark .wk-theme-v9-wash{
  background:radial-gradient(circle at 50% 50%,rgba(119,151,239,.22),transparent 34%),linear-gradient(145deg,#111C2A,#0F1722 58%,#09111B);
}
.wk-theme-v9-overlay.to-light .wk-theme-v9-wash{
  background:radial-gradient(circle at 50% 50%,rgba(255,217,111,.36),transparent 35%),linear-gradient(145deg,#FFF,#F8FAFD 58%,#EDF4FF);
}
.wk-theme-v9-badge{
  position:absolute;left:var(--wk-theme-ix);top:var(--wk-theme-iy);width:82px;height:82px;
  transform:translate(-50%,-50%) scale(.4) rotate(-28deg);display:grid;place-items:center;
  border-radius:28px;opacity:0;box-shadow:0 22px 58px rgba(0,0,0,.24),inset 0 1px 0 rgba(255,255,255,.42);
  backdrop-filter:blur(10px);
}
.wk-theme-v9-badge .wk-inline-icon{width:38px;height:38px}
.wk-theme-v9-overlay.to-dark .wk-theme-v9-badge{color:#F4F7FF;background:linear-gradient(145deg,#718EE5,#35466F);border:1px solid rgba(227,234,255,.32)}
.wk-theme-v9-overlay.to-light .wk-theme-v9-badge{color:#805E00;background:linear-gradient(145deg,#FFF4B8,#FFD15E);border:1px solid rgba(255,255,255,.74)}
.wk-theme-v9-particle{position:absolute;left:var(--wk-theme-ix);top:var(--wk-theme-iy);width:8px;height:8px;border-radius:50%;opacity:0}
.wk-theme-v9-overlay.to-dark .wk-theme-v9-particle{background:#DDE7FF;box-shadow:0 0 13px #9FB7FF}
.wk-theme-v9-overlay.to-light .wk-theme-v9-particle{background:#FFD15E;box-shadow:0 0 13px #FFD15E}
html.wk-theme-v9-changing :is(.app,.top-nav,.bottom-nav){animation:wkSurfaceShift .72s ease both!important}
@keyframes wkSurfaceShift{0%,100%{filter:saturate(1) brightness(1);transform:scale(1)}45%{filter:saturate(.9) brightness(.975);transform:scale(.997)}}


html[data-wk-motion="full"] :is(.btn,.control-btn,.drop-item,.nav-link,.side-btn,.home-quick-card,.info-card,.vocab-card){
  transition:transform .24s var(--wk-motion-ease),box-shadow .24s ease,background-color .22s ease,color .22s ease,border-color .22s ease!important;
