/* source-style: wikaru-all-category-layout-final */
/*
  Final special-quiz isolation.
  Each appendix quiz owns the whole quiz canvas. Normal flashcards and the
  normal control panel must never be rendered together with a special quiz.
*/
body:is(.number-quiz-active,.marker-quiz-active,.duration-quiz-active,.counter-quiz-active) #quizPage{
  width:min(1480px,calc(100% - 44px))!important;
  margin-inline:auto!important;
  padding:14px 0 28px!important;
}
body:is(.number-quiz-active,.marker-quiz-active,.duration-quiz-active,.counter-quiz-active) #quizPage>.notice{
  display:none!important;
}
body:is(.number-quiz-active,.marker-quiz-active,.duration-quiz-active,.counter-quiz-active) #quizPage>.quiz-grid{
  display:block!important;
  grid-template-columns:none!important;
  width:100%!important;
  max-width:1400px!important;
  margin-inline:auto!important;
  overflow:visible!important;
}

/* Kata Bilangan: panel is inside quiz-card-wrap. */
body.number-quiz-active #quizPage>.quiz-grid>.quiz-card-wrap{
  display:block!important;
  width:100%!important;
  min-width:0!important;
  min-height:0!important;
  height:auto!important;
  max-height:none!important;
  padding:0!important;
  border:0!important;
  background:transparent!important;
  box-shadow:none!important;
  overflow:visible!important;
}
body.number-quiz-active #quizPage .quiz-card-wrap>.flashcard,
body.number-quiz-active #quizPage>.quiz-grid>.control-panel{
  display:none!important;
  visibility:hidden!important;
  pointer-events:none!important;
}
body.number-quiz-active #numberQuizPanel{
  display:block!important;
  visibility:visible!important;
  width:100%!important;
  min-width:0!important;
  opacity:1!important;
}

/* Penanda Waktu and Durasi: special panel is inside quiz-card-wrap. */
body:is(.marker-quiz-active,.duration-quiz-active) #quizPage>.quiz-grid>.quiz-card-wrap{
  display:block!important;
  width:100%!important;
  min-width:0!important;
  min-height:0!important;
  height:auto!important;
  max-height:none!important;
  padding:0!important;
  border:0!important;
  background:transparent!important;
  box-shadow:none!important;
  overflow:visible!important;
}
body:is(.marker-quiz-active,.duration-quiz-active) #quizPage .quiz-card-wrap>.flashcard,
body:is(.marker-quiz-active,.duration-quiz-active) #quizPage>.quiz-grid>.control-panel{
  display:none!important;
  visibility:hidden!important;
  pointer-events:none!important;
}
body.marker-quiz-active #markerQuizPanel,
body.duration-quiz-active #durationQuizPanel{
  display:block!important;
  visibility:visible!important;
  width:100%!important;
  min-width:0!important;
  opacity:1!important;
}

/* Kata Bantu Bilangan: panel is a direct child of quiz-grid. */
body.counter-quiz-active #quizPage>.quiz-grid>.quiz-card-wrap,
body.counter-quiz-active #quizPage>.quiz-grid>.control-panel{
  display:none!important;
  visibility:hidden!important;
  pointer-events:none!important;
}
body.counter-quiz-active #counterQuizPanel{
  display:block!important;
  visibility:visible!important;
  width:100%!important;
  min-width:0!important;
  opacity:1!important;
}

/* Never allow an old category panel to remain visible. */
body.number-quiz-active :is(#markerQuizPanel,#durationQuizPanel,#counterQuizPanel),
body.marker-quiz-active :is(#numberQuizPanel,#durationQuizPanel,#counterQuizPanel),
body.duration-quiz-active :is(#numberQuizPanel,#markerQuizPanel,#counterQuizPanel),
body.counter-quiz-active :is(#numberQuizPanel,#markerQuizPanel,#durationQuizPanel){
  display:none!important;
  visibility:hidden!important;
  pointer-events:none!important;
}

/* Restore normal flashcard mode only when no special category quiz is active. */
body:not(.number-quiz-active):not(.marker-quiz-active):not(.duration-quiz-active):not(.counter-quiz-active) #quizPage>.quiz-grid>.quiz-card-wrap,
body:not(.number-quiz-active):not(.marker-quiz-active):not(.duration-quiz-active):not(.counter-quiz-active) #quizPage>.quiz-grid>.control-panel{
  visibility:visible!important;
  pointer-events:auto!important;
}

/* Desktop/tablet landscape: main question left, answer tools right. */
@media (min-width:1024px){
  body.number-quiz-active .number-quiz-workspace{
    display:grid!important;
    grid-template-columns:minmax(0,1fr) minmax(390px,420px)!important;
    gap:18px!important;
    align-items:stretch!important;
  }
  body:is(.marker-quiz-active,.duration-quiz-active) .marker-question-card.marker-question-card-ref{
    display:grid!important;
    grid-template-columns:minmax(0,1fr) minmax(390px,420px)!important;
    gap:18px!important;
    align-items:stretch!important;
  }
  body.counter-quiz-active .counter-question-layout{
    display:grid!important;
    grid-template-columns:minmax(0,1fr) minmax(390px,420px)!important;
    gap:18px!important;
    align-items:stretch!important;
  }

  body.number-quiz-active :is(.number-quiz-workspace,.number-question-stage,.number-response-card),
  body:is(.marker-quiz-active,.duration-quiz-active) :is(.marker-question-card,.marker-main-stage,.marker-side-stack),
  body.counter-quiz-active :is(.counter-question-layout,.counter-question-stage,.counter-answer-panel){
    max-height:none!important;
    overflow:visible!important;
    overflow-y:visible!important;
    overscroll-behavior:auto!important;
    scrollbar-gutter:auto!important;
  }
}

/* Tablet portrait/mobile: deliberate single-column layout. */
@media (max-width:1023px){
  body:is(.number-quiz-active,.marker-quiz-active,.duration-quiz-active,.counter-quiz-active) #quizPage{
    width:min(100% - 22px,1480px)!important;
    padding-top:10px!important;
  }
  body.number-quiz-active .number-quiz-workspace,
  body:is(.marker-quiz-active,.duration-quiz-active) .marker-question-card.marker-question-card-ref,
  body.counter-quiz-active .counter-question-layout{
    grid-template-columns:minmax(0,1fr)!important;
    gap:14px!important;
  }
  body.number-quiz-active :is(.number-question-stage,.number-response-card),
  body:is(.marker-quiz-active,.duration-quiz-active) :is(.marker-main-stage,.marker-side-stack),
  body.counter-quiz-active :is(.counter-question-stage,.counter-answer-panel){
    width:100%!important;
    min-width:0!important;
    height:auto!important;
    max-height:none!important;
  }
}

