/* source-style: wikaru-bab28-reading-motion-final */
/*
    Tujuan patch:
    1) Menampilkan hiragana dan romaji Bab 28 secara bersih tanpa label tambahan.
    2) Menyamakan motion hover/focus kartu dengan kartu kosakata Materi Umum (mis. Bab 1).
    3) Tetap ramah keyboard, dark mode, perangkat sentuh, dan prefers-reduced-motion.
  */

  body.housing-reference-active #materialPage .housing-vocab-card {
    overflow:hidden !important;
    isolation:isolate;
    cursor:default;
    transform:translateZ(0);
    backface-visibility:hidden;
    -webkit-backface-visibility:hidden;
    will-change:transform,box-shadow,border-color;
    transition:
      transform .18s ease,
      border-color .18s ease,
      box-shadow .18s ease,
      background-color .22s ease !important;
    animation:wikaruBab28CardReveal .36s cubic-bezier(.2,.78,.22,1) backwards;
  }

  body.housing-reference-active #materialPage .housing-vocab-card:nth-child(4n + 2) { animation-delay:.025s; }
  body.housing-reference-active #materialPage .housing-vocab-card:nth-child(4n + 3) { animation-delay:.05s; }
  body.housing-reference-active #materialPage .housing-vocab-card:nth-child(4n + 4) { animation-delay:.075s; }

  @keyframes wikaruBab28CardReveal {
    from { opacity:0; transform:translateY(9px); }
    to   { opacity:1; transform:translateY(0); }
  }

  body.housing-reference-active #materialPage .housing-vocab-card::before {
    z-index:0;
    width:4px !important;
    opacity:.72;
    transform:scaleY(.42);
    transform-origin:center;
    transition:transform .22s cubic-bezier(.2,.78,.22,1),opacity .22s ease,background .22s ease;
  }

  body.housing-reference-active #materialPage .housing-vocab-card::after {
    content:"";
    position:absolute;
    z-index:0;
    inset:0;
    pointer-events:none;
    opacity:0;
    background:radial-gradient(circle at 92% 8%,rgba(36,59,115,.085),transparent 34%);
    transition:opacity .22s ease;
  }

  body.housing-reference-active #materialPage .housing-vocab-card > * {
    position:relative;
    z-index:1;
  }

  @media (hover:hover) and (pointer:fine) {
    body.housing-reference-active #materialPage .housing-vocab-card:hover {
      transform:translateY(-3px);
      border-color:rgba(36,59,115,.28) !important;
      box-shadow:0 12px 30px rgba(35,42,32,.095) !important;
    }
    body.housing-reference-active #materialPage .housing-vocab-card:hover::before {
      transform:scaleY(1);
      opacity:1;
      background:linear-gradient(var(--primary,#243B73),var(--accent,#E84B3C)) !important;
    }
    body.housing-reference-active #materialPage .housing-vocab-card:hover::after { opacity:1; }
  }

  body.housing-reference-active #materialPage .housing-vocab-card:focus-within {
    transform:translateY(-3px);
    border-color:rgba(36,59,115,.34) !important;
    box-shadow:0 0 0 4px rgba(36,59,115,.08),0 12px 30px rgba(35,42,32,.095) !important;
  }
  body.housing-reference-active #materialPage .housing-vocab-card:focus-within::before {
    transform:scaleY(1);
    opacity:1;
    background:linear-gradient(var(--primary,#243B73),var(--accent,#E84B3C)) !important;
  }
  body.housing-reference-active #materialPage .housing-vocab-card:focus-within::after { opacity:1; }

  /* Blok cara baca: hiragana dibuat jelas, rapi, dan tidak lagi terasa seperti teks abu-abu lepas. */
  body.housing-reference-active #materialPage .housing-reading-stack {
    display:grid !important;
    grid-template-columns:minmax(0,1fr) auto;
    align-items:center;
    gap:7px 9px !important;
    min-height:0;
    margin-top:8px !important;
  }

  body.housing-reference-active #materialPage .housing-kana {
    grid-column:1 / -1;
    min-width:0;
    display:flex;
    align-items:center;
    gap:0;
    padding:8px 11px;
    border:1px solid rgba(36,59,115,.12);
    border-radius:12px;
    background:linear-gradient(135deg,rgba(233,237,250,.94),rgba(245,248,255,.92));
    color:#243B73 !important;
    font-family:var(--jp) !important;
    font-size:14px !important;
    line-height:1.45 !important;
    font-weight:700 !important;
    letter-spacing:.025em !important;
