/* UX FIX v2 — pilihan tetap jelas, tetapi motion dibuat ringan dan cepat. */
#setupSelectionLive{
  min-height:30px;margin:-5px 0 10px;display:flex;align-items:center;gap:8px;padding:6px 10px;
  border-radius:12px;border:1px solid rgba(49,95,174,.14);background:rgba(244,248,255,.86);
  color:#315786;font-size:11px;font-weight:750;line-height:1.35;opacity:0;transform:translateY(-2px);
  pointer-events:none;transition:opacity .14s ease,transform .16s ease,border-color .16s ease,background .16s ease
}
#setupSelectionLive.is-visible{opacity:1;transform:none}
#setupSelectionLive .wk-selection-check{
  width:8px;height:8px;display:block;flex:0 0 auto;border-radius:50%;background:#2F6BB1;
  box-shadow:0 0 0 0 rgba(47,107,177,.18);animation:wkSelectionDot .28s ease-out both
}
#setupSelectionLive .wk-selection-check i{display:none!important}
#setupSelectionLive strong{color:inherit;font-weight:850}

#setupModal #setupMaterialGrid .option-card.active,
#setupModal #setupChapterGrid .category-button.active{
  position:relative!important;border-color:#315FAE!important;background:linear-gradient(145deg,#315FAE,#294F8D)!important;
  color:#fff!important;box-shadow:0 8px 18px rgba(36,74,134,.14)!important;
  transform:translateY(-1px)!important
}
#setupModal #setupMaterialGrid .option-card.active :is(div,strong,span,small,i),
#setupModal #setupChapterGrid .category-button.active :is(div,strong,span,small,i){color:#fff!important}
#setupModal #setupMaterialGrid .option-card.active small,
#setupModal #setupChapterGrid .category-button.active small{opacity:.84!important}

/* Badge teks dipilih dihilangkan; titik kecil cukup sebagai penanda. */
#setupModal #setupMaterialGrid .option-card.active::after,
#setupModal #setupChapterGrid .category-button.active::after{
  content:"";position:absolute;top:11px;right:11px;z-index:3;width:7px;height:7px;border-radius:50%;
  background:rgba(255,255,255,.92);box-shadow:0 0 0 3px rgba(255,255,255,.13)
}

#setupModal :is(#setupBookGrid,#setupMaterialGrid,#setupChapterGrid) :is(.option-card,.category-button){
