}
#setupModal :is(#setupBookGrid,#setupMaterialGrid,#setupChapterGrid) :is(.option-card,.category-button).wk-selection-confirm{
  animation:wkSelectionConfirmLite .24s cubic-bezier(.2,.8,.2,1) both!important
}
#setupModal :is(#setupBookGrid,#setupMaterialGrid,#setupChapterGrid) :is(.option-card,.category-button).wk-selection-confirm::before{
  content:"";position:absolute;inset:-2px;border-radius:inherit;border:1px solid rgba(49,95,174,.28);opacity:0;
  pointer-events:none;animation:wkSelectionRingLite .26s ease-out both!important
}
@keyframes wkSelectionConfirmLite{0%{transform:scale(.992)}55%{transform:scale(1.006)}100%{transform:scale(1)}}
@keyframes wkSelectionRingLite{0%{opacity:.45;transform:scale(.992)}100%{opacity:0;transform:scale(1.025)}}
@keyframes wkSelectionDot{0%{transform:scale(.65);opacity:.35}100%{transform:scale(1);opacity:1}}

html[data-theme="dark"] #setupSelectionLive{background:rgba(29,42,62,.88);border-color:#38516C;color:#DCE8FF}
