/* source-style: wikaru-qa-release-fixes-v2 */
:root{
    --wk-release-gutter:clamp(18px,3vw,44px);
    --wk-release-gap:clamp(16px,2vw,24px);
    --wk-release-card-radius:24px;
    --wk-release-control-radius:15px;
    --wk-release-touch:48px;
    --wk-release-focus:rgba(49,95,174,.34);
  }

  /* Interaction, cursor, focus, and safe overlay states. */
  html,body{max-width:100%;overflow-x:clip;text-size-adjust:100%;-webkit-text-size-adjust:100%}
  body{text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;-webkit-tap-highlight-color:transparent}
  :where(.app,.page,.layout,.content-card,.quiz-grid,.control-panel,.modal-card,.modal-scroll-body,.vocab-grid,.admin-report-card,.home-main-grid,.home-card){min-width:0}
  :where(button:not(:disabled),a[href],[role="button"]:not([aria-disabled="true"]),summary,label[for],select,input[type="checkbox"],input[type="radio"],input[type="range"]){cursor:pointer!important;touch-action:manipulation}
  :where(button:disabled,[aria-disabled="true"],.disabled){cursor:not-allowed!important}
  :where(input:not([type]),input[type="text"],input[type="search"],input[type="password"],input[type="email"],input[type="number"],textarea,[contenteditable="true"]){cursor:text!important;caret-color:var(--primary,#243B73)}
  :where(button,a[href],[role="button"],input,select,textarea,summary):focus-visible{outline:3px solid var(--wk-release-focus)!important;outline-offset:3px!important}
  :where(button,.btn,.icon-btn,.control-btn,.option-card,.choice-chip,.check-pill,.bottom-nav button){-webkit-tap-highlight-color:transparent}
  :where(.modal:not(.show),.dropdown:not(.show),.profile-menu-backdrop:not(.show),#loadingScreen[aria-hidden="true"],#devtoolsOverlay){pointer-events:none!important}
  #loadingScreen[aria-hidden="true"],#devtoolsOverlay{display:none!important}
  [hidden]{display:none!important}
  main :is(p,h1,h2,h3,h4,td,th,.jp,.reading,.meaning,.example-info-card){user-select:text}
  ::selection{background:rgba(49,95,174,.20);color:inherit}

  /* Stable media, long text, tables, and card rhythm. */
  img,svg,video,canvas{max-width:100%}
  :where(h1,h2,h3,h4,p,strong,small,.jp,.reading,.meaning,.home-active-choice,.question-text){overflow-wrap:anywhere}
  :where(.table-card,.table-wrap,.admin-table-wrap,.counter-table,.marker-table,.postal50-table-wrap){max-width:100%;overflow-x:auto;overscroll-behavior-inline:contain;-webkit-overflow-scrolling:touch}
