  html[data-theme="dark"] .quiz-count-field{background:#222a37;border-color:#3b4659}
  html[data-theme="dark"] .quiz-count-title{color:#f4f7ff}
  html[data-theme="dark"] .quiz-count-field small{color:#b7c0cf}

  /* Render large material collections only when they approach the viewport. */
  @supports(content-visibility:auto){
    #materialGrid>:is(.vocab-card,.road-vocab-card,.life-cycle-card,.verb-conj-card,.counter-group-card,.postal50-vocab-card,.useful41-panel),
