  @media (hover:hover) and (pointer:fine){
    :where(.btn,.icon-btn,.control-btn,.option-card,.choice-chip,.check-pill,.home-quick-item,.bottom-nav button):not(:disabled):hover{will-change:transform}
  }
  @media (hover:none){
    :where(.btn,.icon-btn,.control-btn,.option-card,.choice-chip,.check-pill,.home-card,.vocab-card):hover{transform:none!important}
  }
  @media (pointer:coarse){
    :where(button,.btn,.icon-btn,.control-btn,.choice-chip,.check-pill,select,input){min-height:var(--wk-release-touch)}
  }

  /* iPad and tablet: one calm content column with a bottom dock. */
  @media (min-width:768px) and (max-width:1180px){
