      top:auto!important;bottom:14px!important;left:50%!important;right:auto!important;transform:translateX(-50%)!important;
      width:min(640px,calc(100% - 36px))!important;height:auto!important;
      grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:7px!important;
